                                ‫ـرر َّ‬   ‫املدعِ ــي ـ قـ َ‬      ‫ن املطلوب ـ َة ـ احلكـ ُـم بــر ِّد َدعـ َـوى َّ‬                               ‫اليم ـ َ‬\n‫ـتئناف يف َجلسـ ٍة ُأخـ َـرى‬                 ‫ـات االسـ ِ‬               ‫وإفهامــه بتعليمـ ِ‬  ‫َ‬                 ‫ع َلــى احلكـ ِـم بالئحـةٍ‪،‬‬\n‫ـاء‬                                                     ‫رضــي ُ‬             ‫بقــولِ عمـ َـر ِ‬\n  ‫مينعـ َـك قضـ ُ‬           ‫اهلل عن ـ ُه‪( :‬وال ُ‬                                                        ‫الدعـ َـوى َ‬     ‫اســتدلَّ ناظـ ُـر َّ‬\n‫لرشــدِ َك أنْ ترجـ َـع‬                    ‫وهديـ َـت في ـ ِه ُ‬          ‫نفسـ َـك ُ‬    ‫ـس راجعـ َـت في ـ ِه َ‬               ‫قضي ِتــه باألمـ ِ‬\n‫ناشــئ ٌة َعــن‬    ‫املدعِ ــي بطلـ ِـب إعــاد ِة البلـ ِـك حمل ِّلـ ِه ِ‬                       ‫إن دعـ َـوى َّ‬       ‫ـث َّ‬         ‫للحـ ِّـق)‪ ..‬وحيـ ُ‬\n‫ـاص‬    ‫ـوت ال َّتم ُّلـ ِـك مِ ــن اخ ِتصـ ِ‬          ‫إن ال َّنظـ َـر يف ثبـ ِ‬            ‫ـث َّ‬   ‫األرض‪ ،‬وحيـ ُ‬       ‫ِ‬                 ‫ـات مت ُّلـ ِـك‬‫إثبـ ِ‬\n‫دعو ُاه يف احملكم ِة‬                   ‫أن لـ ُه إقام َة َ‬         ‫املدعِ ــي َّ‬     ‫ـام َّ‬\n                                                                                        ‫مت إفهـ ُ‬        ‫فقــد َّ‬‫العامـ ِة َ‬‫َّ‬             ‫احملك ِمــة‬\n‫املدعِ ــي‬    ‫ـرر َّ‬  ‫ـاص وقـ َ‬           ‫ـدم االخ ِتصـ ِ‬        ‫ـواه لعـ ِ‬        ‫ـرف النظـ ِـر َعــن دعـ ُ‬                     ‫العام ـ ِة وصـ َ‬       ‫َّ‬\n‫ـتئناف‪،‬‬ ‫ِ‬           ‫ـات االسـ‬       ‫إفهامــه بتعليمـ ِ‬   ‫ُ‬                  ‫مت‬\n                                                                             ‫اعتراض ـ ُه علــى ا ُحلكـ ِـم بالئح ـةٍ‪ ،‬و َّ‬                        ‫َ‬\n                                                             ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                                                                                                    ‫‪174‬‬\n\f      ‫ـدي أنــا (‪ )...‬القاضــي يف احملكمــة اجلزائيــة‬ ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n      ‫ـاء علــى املعاملــة احملالــة إلينــا من قِ بل فضيلــة رئيس احملكمة‬ ‫بتبــوك وبنـ ً‬\n      ‫اجلزائيــة بتبوك‪/‬املســاعد برقــم ‪ 33335945‬وتاريــخ ‪1433/05/15‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33913000‬وتاريــخ ‪1433/05/15‬هــ‪ ..‬ففــي‬\n      ‫يــوم األحــد املوافــق ‪1433/06/15‬ه ـ حضــر (‪ )...‬ســعودي مبوجــب‬\n      ‫ســجل مدنــي رقــم (‪ )...‬وادعــى علــى احلاضــر (‪ )...‬ســعودي مبوجــب‬\n      ‫ســجل مدنــي رقــم (‪ )...‬قائـ ًـا يف دعــواه‪ :‬لقــد قمــت بوضــع ألــف بلكــة‬\n      ‫لتســوير أرض لــي‪ ،‬فقــام املدعــى عليــه األول احلاضــر بتكســير مائــة‬\n      ‫وثــاث وخمســن بلكــة وقــام بنقــل ثمامنائــة وســبع وأربعــن بلكــة قرابــة‬\n      ‫مائــة متــر وقــام بوضعهــا شــرق الطريــق؛ لــذا أطلــب إلزامــه بإعــادة البلــك‬\n      ‫حمللــه وتعويضــي عــن البلــك املكســور؛ هــذه دعــواي‪ .‬وبســؤال املدعــى‬\n      ‫عليــه قــال مــا ذكــره املدعــي مــن قيامــي بنقــل البلــك فصحيــح‪ ،‬وذلــك‬\n      ‫إلبعــاده عــن حــرم الطريــق‪ ..‬أمــا قيامــي بتكســير البلــك فــا صحــة‬\n      ‫لــه كمــا أن مركــز البديعــة لديــه علــم بهــذا األمــر وصــدر محضــر‬\n      ‫بالواقعــة؛ هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي قــال‪ :‬الصحيــح‬\n      ‫مــا جــاء يف دعــواي‪ ،‬أمــا حتريــر احملضــر فصحيــح لــذا ُرفعــت اجللســة‬\n      ‫للكتابــة ملركــز البديعــة ‪ .‬ويف يــوم األحــد املوافــق ‪1434/03/29‬ه ـ‬\n      ‫حضــر الطرفــان ووردتنــا إفــادة شــرطة مركــز البديعــة بــدون رقــم‬\n      ‫وتاريــخ ‪1433/7/11‬ه ـ محضــر معاينــة يف متــام الســاعة احلاديــة عشــرة‬\n      ‫مــن يــوم اإلثنــن املوافــق ‪1433/7/11‬هــ‪ ،‬وردنــا خطــاب مركــز إمــارة‬\n      ‫البديعــة رقــم ‪ 99‬بتاريــخ ‪1433/7/11‬ه ـ واملتضمــن شــكوى املواطــن‬\n\n‫‪175‬‬\n\f                                                                     ‫(‪ )...‬ضــد ٍّ‬\n‫كل مــن (‪ )...‬واملواطــن (‪ ،)...‬وانتقلنــا ملعاينــة املوقــع فوجدنــا‬\n‫علمــا بــأن األرض بيضــاء‪،‬‬   ‫ـكا مكسـ ًـرا‪ً ،‬‬     ‫بــاألرض املتنــازع عليهــا بلـ ً‬\n‫وحفظــا للواقــع فقــد نظــم هــذا احملضــر‬‫ً‬      ‫وهــذا مــا وجدنــاه يف املوقــع‪..‬‬\n‫مــن قِ بــل مخفــر شــرطة البديعــة‪ ..‬وبســؤال املدعــي ألديــه مزيــد بينــة‪،‬‬\n‫قــال‪ :‬ال‪ .‬وأطلــب ميــن املدعــى عليــه علــى عــدم تكســيره للبلــك‪ ،‬وبعرض‬\n‫ذلــك علــى املدعــى عليــه اســتعد بذلــك ثــم حلــف قائـ ًـا‪ :‬واهلل العظيــم‬\n‫أننــي لــم أقــم بتكســير البلــك العائــد للمدعــي‪ ،‬وبســؤال املدعــى عليــه‬\n‫عــن ســبب نقلــه للبلــك قــال‪ :‬البلــك وضعــه يف حــرم أرض والــدي؛ لــذا‬\n‫فــا حــق لــه يف وضــع البلــك وبعــرض ذلــك علــى املدعــي قــال إن األرض‬\n‫ـاء علــى مــا‬\n            ‫عائــدة لــي‪ ،‬وبســؤاله‪ :‬ألديــه إثبــات متلــك لهــا قــال ال‪ ،‬وبنـ ً‬\n‫تقــدم مــن الدعــوى واإلجابــة وملصادقــة املدعــى عليــه علــى نقلــه للبلــك‬\n‫وإلقــرار املدعــي علــى عــدم وجــود مــا يثبــت متلكــه‪ ،‬وحيــث إن القاعــدة‬\n‫الفقهيــة (مــا ترتــب علــى غيــر املــأذون غيــر مضمــون)‪ ،‬وحيــث إن املدعي‬\n‫ال بينــة لــه علــى قيــام املدعــى عليــه بتكســير البلــك‪ ،‬ولقولــه صلــى‬\n‫اهلل عليــه وســلم‪« :‬البينــة علــى مــن ادعــى واليمــن علــى مــن أنكــر»‪،‬‬\n‫ولطلبــه اليمــن وحلــف املدعــي عليــه اليمــن املطلوبــة لــذا حكمــت‬\n‫بــرد دعــوى املدعــي‪ ..‬وبعــرض ذلــك علــى املدعــي قــرر اعتراضــه بالئحــة‬\n‫وســيجري تســليمه نســخة مــن احلكــم بعــد التوقيــع علــى الضبــط‪ ،‬ومت‬\n‫يومــا مــن تســلمه‬\n                  ‫إفهامــه بتقــدمي الالئحــة االعتراضيــة خــال ثالثــن ً‬\n‫نســخة احلكــم وإال سيســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n‫القطعيــة‪ ،‬ويصبــح واجــب النفــاذ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n                          ‫ُحــرر الســاعة الثانيــة عشــرة يف ‪1434/3/29‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬إنــه يف يــوم اإلثنــن املوافــق ‪1434/04/01‬ه ـ‬\n\n\n                                                                                       ‫‪176‬‬\n\f      ‫افتتحــت اجللســة يف الســاعة العاشــرة وخمــس وأربعــن دقيقــة‪ ،‬وفيهــا‬\n      ‫حضــر املدعــي‪ ..‬ولقــول عمــر رضــي اهلل عنــه‪( :‬وال مينعــك قضــاء قضيتــه‬\n      ‫باألمــس راجعــت فيــه نفســك وهديــت فيــه لرشــدك أن ترجــع للحــق)‪،‬‬\n      ‫وحيــث إن دعــوى املدعــي بطلــب إعــادة البلــك حمللــه ناشــئة عــن إثبــات‬\n      ‫متلــك األرض وحيــث إن النظــر يف ثبــوت التملــك اختصــاص احملكمــة‬\n      ‫ـواه يف احملكمــة العامــة‪ ،‬وصرفــت‬     ‫العامــة؛ لــذا أفهمتــه أن لــه إقامــة دعـ ُ‬\n      ‫النظــر عــن دعــواه‪ .‬وبعــرض ذلــك علــى املدعــي قــرر اعتراضــه علــى‬\n      ‫احلكــم بالئحــة‪ ،‬وســيجري تســليمه نســخة مــن احلكــم بعــد التوقيــع‬\n      ‫علــى الضبــط‪ ،‬ومت إفهامــه بتقــدمي الالئحــة االعتراضيــة خــال ثالثــن‬\n      ‫يومــا مــن تســلمه نســخة احلكــم وإال سيســقط حقــه يف االعتــراض‬                ‫ً‬\n      ‫ويكتســب احلكــم القطعيــة ويصبــح واجــب النفــاذ‪ ،‬وصلــى اهلل وســلم‬\n       ‫علــى نبينــا محمــد‪ُ .‬حــرر الســاعة احلاديــة عشــرة يف ‪1434/04/01‬هــ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل‪ ..‬أمــا بعــد‪ ،‬فقــد اطلعن ــا‬\n      ‫نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة‬\n      ‫تبــوك علــى املعاملــة الــواردة مــن رئيــس احملكمــة اجلزائيــة بتبــوك‬\n      ‫املكلــف برقــم ‪ 33913000‬وتاريــخ ‪1434/5/29‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر عــن فضيلــة الشــيخ (‪ )...‬ـ ـ وفقــه اهلل ـ ـ برقــم ‪ .........‬وتاريــخ‬\n      ‫‪1434/3/29‬ه ـ اخلــاص بدعــوى (‪ )...‬ضــد (‪ ،)...‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة املقدمــة مــن املدعــي وأوراق‬\n      ‫املعاملــة جــرت املصادقــة علــى احلكــم مــع التنبيــه علــى أن عــدم‬\n      ‫االختصــاص راجــع لكونهــا مــن دعــاوى التعــرض للحيــازة يف العقــار‪.‬‬\n      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n‫‪177‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":173,"source_page_end":177,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d94cf763ff9b1f9cd5a36b40d2840c174fef92e8177223993884484f28f959f1","normalized_text_hash":"b770b6096ea002bb2c78506bdbe5efef15f57cfe7edd61fad83c591647b6584f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p173-34175102"},{"id":"436c4d8f-8bfc-5255-9c63-f0c343dfbdff","document_type":"judgment","category":"judicial","subcategory":"general","title":"صاحب ة اختصاص -دع وى ض د جه ة حكومي ة -احملكم ة اإلدار ي ة اص م ن ال نظا م الدعا وى -مسأل ة االختص اص بنظ ر هذ ه االختص دون دف ع أ و حضو ر م ن تقضي ب ه احملكم ة م ن تلقاء","document_number":"3423576","case_number":"33613716","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"صاحب ة اختصاص -دع وى ض د جه ة حكومي ة -احملكم ة اإلدار ي ة اص م ن ال نظا م الدعا وى -مسأل ة االختص اص بنظ ر هذ ه االختص دون دف ع أ و حضو ر م ن تقضي ب ه احملكم ة م ن تلقاء","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3423576 :‬‬\n                   ‫َر ْق ُم الدعوى‪33613716 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34207573‬تاريخه‪1434/5/6 :‬هـ‬\n\n\n       ‫ِ‬\n‫صاحب ـ ُة‬         ‫اختصــاص ‪َ -‬دعْ ـ َوى ِضـ َّـد ِجه ـ ٍة ُحكومي ـ ٍة ‪ -‬احملكم ـ ُة اإلدار َّي ـ ُة‬\n‫ـاص مـ َـن ال ِّنظــا ِم‬     ‫الدعــا َوى ‪ -‬مســأل ُة االختصـ ِ‬    ‫ـاص بنظ ـ ِر هــذ ِه َّ‬  ‫االختصـ ِ‬\n‫دون َدفـ ٍـع أ ْو ُحضــو ٍر مـ َـن‬             ‫تقضــي ب ـ ِه احملكم ـ ُة مِ ــن َتلقــاءِ ِ‬\n                                        ‫نفســها َ‬                                           ‫العــا ِّم ِ‬\n           ‫ـاص ال َّن ْوعـ ِّـي‪.‬‬‫ـرف ال َّنظ ـ ِر لعــد ِم االختصـ ِ‬  ‫بصـ ِ‬   ‫احل ْكـ ُـم َ‬\n                                                                                       ‫اخلصــو ِم ‪ُ -‬‬\n\n\n\n\n                  ‫الم‪.‬‬ ‫عشر َة مِ ن نظا ِم دِيوانِ َ‬\n                   ‫املظ ِ‬                                                  ‫الفِ ْقر ُة (ج) َ‬\n                                                 ‫من املا َّد ِة الثال َث َة َ‬\n\n\n\n\n‫رات‪ ،‬ولـ ْـم يحضـ ْـر‬       ‫املدعِ ــي َدعـ َـو ُاه ِضـ َّـد إدار ِة ُمكافح ـ ِة املخـ ِّـد ِ‬            ‫ـام َّ‬   ‫أقـ َ‬\n‫أن‬ ‫ـاده َّ‬          ‫أرســلَ خِ ً‬\n          ‫طابــا ُمفـ ُ‬            ‫أن مديـ َـر اإلدار ِة َ‬         ‫ـدوب اإلدار ِة رغـ َـم تبلي ِغــه َّإل َّ‬  ‫منـ ُ‬\n‫أن هــذ ِه‬  ‫ومبــا َّ‬\n                  ‫فقــط ‪َ ،‬‬       ‫ـض َ‬    ‫بالدعـ َـوى؛ أل َّنهــا ِجه ـ ُة قَ ْبـ ٍ‬ ‫اإلدار َة غيـ ُـر َمعني ـ ٍة َّ‬\n‫مبمارس ـ ِة‬     ‫خول ـ ٍة مِ ــن قِ بـ ِـل َولـ ِّـي األمـ ِـر ُ‬\n                                                              ‫الدعـ َـوى ِضـ َّـد ِجه ـ ٍة ُحكومي ـ ٍة ُم َّ‬        ‫َّ‬\n‫ـاص‬     ‫ارج ـ ٌة عـ ِـن اخ ِتصـ ِ‬   ‫ـاوى َخ َ‬       ‫الدعـ َ‬‫وألن مِ ثــلَ هــذ ِه َّ‬     ‫َّ‬       ‫ِصاصهــا ‪،‬‬‫اخت ِ‬\n  ‫ـاص احملكم ـ ِة اإلداري ـ ِة َح ْسـ َـبما َو َر َد بنظـ ِ‬\n‫ـام‬                                                                        ‫احملكمـِـة ومِ ــن اختصـ ِ‬\n‫ـاء فِ يهــا‬  ‫عشــر َة بالفِ قــر ِة (ج) ا َّلتــي جـ َ‬                                                 ‫ِديــوانِ َ‬\n                                                             ‫املظالـ ِـم يف املــا َّد ِة الثال َث ـ َة َ‬\n                     ‫ِ‬\n     ‫ـرارات ْأو أعمــالِ‬     ‫الشــأنِ َعــن قـ‬   ‫قد ُمهــا َذوو َّ‬    ‫ـض ا َّلتــي ُي ِّ‬   ‫ـاوى ال َّتعويـ ِ‬‫أن َدعـ َ‬  ‫َّ‬\n‫ـرف‬    ‫ـاص اإلداريـ ِة ‪ ،‬ملــا تقـ َّـد َم صــدر احلكـ ُـم بصـ ِ‬             ‫ِجهـ ِة اإلدار ِة مِ ــن اخ ِتصـ ِ‬\n‫املدعِ ــي بالئحـ ٍة‬   ‫ـرض َّ‬ ‫ـاص ‪ ،‬اعتـ َ‬         ‫ـدم االخ ِتصـ ِ‬      ‫الدعـ َـوى لعـ ِ‬    ‫ال َّنظـ ِـر َعــن هــذ ِه َّ‬\n\n                                                                                                                            ‫‪178‬‬\n\f                     ‫اعتراضي ـةٍ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫ـدي أنــا‪ ...‬القاضــي يف احملكمــة العامــة‬ ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n      ‫ـاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة‬\n                                                                       ‫ـ(ينبــع) وبنـ ً‬\n                                                                                  ‫ب ُ‬\n      ‫العامــة بـ(ينبع)‪/‬املســاعد برقــم ‪ ......‬وتاريــخ ‪1433/10/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ .....‬وتاريــخ ‪1433/10/21‬ه ـ بشــأن دعــوى‪ ...‬ضــد‬\n      ‫ـ(ينبــع)‪ ..‬ففــي يــوم الثالثــاء املوافــق‬\n                                             ‫إدارة مكافحــة املخــدرات ب ُ‬\n      ‫‪1433/12/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر‬\n      ‫املدعــي وكال ـ ًة‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫تخولــه يف‬\n              ‫‪ ....‬مبوجــب وكالتــه رقــم ‪ ........‬يف ‪1433/10/7‬ه ـ التــي ّ‬\n      ‫املطالبــة وإقامــة الدعــاوى‪ ،‬واملرافعــة‪ ،‬واملدافعــة‪ ،‬وســماع الدعــاوى‬\n      ‫والــرد عليهــا‪ ،‬واإلنــكار‪ ،‬واإلقــرار‪ ،‬وطلــب اليمــن ورده واالمتنــاع‬\n      ‫عنــه‪ ،‬وإحضــار الشــهود‪ ،‬والبينــات والطعــن فيهــا‪ ،‬واإلجابــة‪ ،‬واجلــرح‪،‬‬\n      ‫والتعديــل‪ ،‬والطعــن بالتزويــر‪ ،‬وإنــكار اخلطــوط واألختــام‪ ،‬والتوقيــع‪،‬‬\n      ‫وقبــول األحــكام واالعتــراض عليهــا‪ ،‬وطلــب اســتئنافها‪ ..‬ولــم يحضــر‬\n      ‫علمــا بأنــه مت إبالغهــم‪،‬‬\n                              ‫ـ(ينبــع) ً‬\n                                      ‫منــدوب إدارة مكافحــة املخــدرات ب ُ‬\n      ‫وذلــك مبوجــب خطابهــم رقــم ‪ 2428/15‬يف ‪1433/10/25‬ه ـ ر ًّدا‬\n      ‫علــى خطابنــا رقــم ‪ ،331852024‬وذكــروا يف خطابهــم أن جهازهــم‬\n      ‫غيــر معنــي بدعــوى املدعــي؛ ألنهــم جهــة قبــض فقــط و ُأحيلــت القضيــة‬\n      ‫إلــى هيئــة التحقيــق واالدعــاء العــام‪ ،‬ثــم جــرى حتديــد جلســة أخــرى‬\n      ‫والكتابــة لهــم مــرة ثانيــة واملطلــوب هــو حضــور مندوبهــم وســماع مــا‬\n      ‫لديــه‪ ،‬وذلــك يــوم اإلثنــن ‪1434/1/26‬ه ـ يف الســاعة احلاديــة عشــرة‬\n\n‫‪179‬‬\n\f‫صباحــا‪ ..‬ففــي يــوم اإلثنــن املوافــق ‪1434/01/26‬ه ـ افتتحــت اجللســة‬      ‫ً‬\n‫صباحــا‪ ،‬وفيهــا حضــر املدعــي وكال ـ ًة‪ ...‬وقــد‬‫ً‬       ‫الســاعة احلاديــة عشــرة‬\n‫وردنــا خطــاب مديــر مكافحــة املخــدرات برقــم ‪ 1/6/31/15‬يف‬\n‫وبتأمــل الدعــوى وجــدت‬  ‫ُّ‬     ‫‪1434/1/4‬ه ـ ومفــاده أنــه جهــة قبــض فقــط‪،‬‬\n‫أن هــذه الدعــوى دعــوى ضــد جهــة حكوميــة مخولــة مــن قِ بــل ولــي األمــر‬\n‫مبمارســة اختصاصهــا‪ ،‬ونظـ ًـرا ألن مثــل هــذه الدعــاوى خارجــة عــن‬\n‫اختصــاص احملكمــة‪ ،‬ومــن اختصــاص احملكمــة اإلدارية حســبما ورد‬\n‫بنظــام ديــوان املظالــم ومنــه املــادة الثالثــة عشــرة بالفقــرة (ج) التــي جــاء‬\n‫فيهــا قولــه إن دعــاوى التعويــض التــي يقدمهــا ذوو الشــأن عــن قــرارات‬\n‫أو أعمــال جهــة اإلدارة مــن اختصــاص احملكمــة اإلداريــة‪ ..‬وعليــه‪،‬‬\n‫فقــد صرفــت النظــر عــن هــذه الدعــوى لعــدم االختصــاص‪ ،‬وبذلــك‬\n‫حكمــت‪ .‬وبعرضــه علــى املدعــي وكال ـ ًة قــرر قائـ ًـا‪ :‬إننــي غيــر قانــع‬\n‫باحلكــم‪ ..‬و ُأعطــي صــورة مــن القــرار لعمــل الئحتــه االعتراضيــة ومت‬\n‫يومــا‪ ،‬وإذا لــم يقــدم خــال تلــك‬    ‫إفهامــه بــأن مــدة االعتــراض ثالثــون ً‬\n‫املــدة الئحتــه فسيســقط اعتراضــه‪ ،‬ويكتســب احلكــم القطعيــة‪ ..‬بــاهلل‬\n‫التوفيــق‪ ..‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر‬\n                                                           ‫يف ‪1434/01/26‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد‪ ..‬فق ــد ج ــرى مــن‬\n‫قِ ب ِلنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n‫االطــا ُع عل ــى هــذا احلكــم‬   ‫االســتئناف مبنطقــة مك ــة املكرم ــة ِّ‬\n‫ـ(ينبــع)‬\n    ‫الصــادر عــن فضيلــة الشــيخ‪ .../‬القاضــي باحملكمــة العامــة ب ُ‬\n‫واملســجل بع ــدد ‪ 3423576‬وتاريــخ ‪1434/1/26‬هـ ـ املتضمــن دعــوى‪...‬‬\n‫ـ(ينبــع) احملكــوم في ــه مبــا دون باطن الصك‪ ،‬وبدراس ــة احلكم‬\n                                                           ‫ضــد‪ ...‬ب ُ‬\n\n                                                                                        ‫‪180‬‬\n\f      ‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪،‬‬\n      ‫واهلل املوفــق‪ ،‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":178,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"77306652b4d88533f2fb527878b878014c8a733ca550e0c2ed54d352435d09e0","normalized_text_hash":"9dc0cde2b7071c2c6af447c68703f3b4c2d94f13122374006cd43a0f442d51bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p178-3423576"},{"id":"cfd9809f-7505-5cc5-9f82-994f267be7ac","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -عقد بيع -مصاعد وتركيبها -تعويض عن ضرر تنفيذ العقد -الدفع بوجوب اللجوء للتحكيم الشتراطه يف العقد -املدعى ناظر وقف ال يبطل شرط التحكيم -احلكم بعدم جواز نظر المحكمة القضية لتحقق شرط التحكيم -وجوب رفع احلكم حملكمة الاستئناف كونه حكم صدر بعدم جواز نظر دعوى ناظر الوقف لعدم االختصاص .1املادة احلادية عشرة من نظام التحكيم.","document_number":"3419952","case_number":"33699557","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/21","year":"1434","subject":"اختصاص -عقد بيع -مصاعد وتركيبها -تعويض عن ضرر تنفيذ العقد -الدفع بوجوب اللجوء للتحكيم الشتراطه يف العقد -املدعى ناظر وقف ال يبطل شرط التحكيم -احلكم بعدم جواز نظر المحكمة القضية لتحقق شرط التحكيم -وجوب رفع احلكم حملكمة الاستئناف كونه حكم صدر بعدم جواز نظر دعوى ناظر الوقف لعدم االختصاص .1املادة احلادية عشرة من نظام التحكيم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3419952 :‬‬\n                         ‫َر ْق ُم الدعوى‪33699557 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34179473‬تاريخه‪1434/4/6 :‬هـ‬\n\n\n      ‫اختصــاص‪ -‬عقــد بيــع ‪ -‬مصاعــد وتركيبهــا ‪ -‬تعويــض عــن ضــرر‬\n      ‫تنفيــذ العقــد ‪ -‬الدفــع بوجــوب اللجــوء للتحكيــم الشــتراطه يف العقــد‬\n      ‫‪ -‬املدعــى ناظــر وقــف ال يبطــل شــرط التحكيــم ‪ -‬احلكــم بعــدم جــواز‬\n      ‫نظــر احملكمــة القضيــة لتحقــق شــرط التحكيــم ‪ -‬وجــوب رفــع احلكــم‬\n      ‫حملكمــة االســتئناف كونــه حكــم صــدر بعــدم جــواز نظــر دعــوى ناظــر‬\n                                                    ‫الوقــف لعــدم االختصــاص‬\n\n\n\n\n                                          ‫‪ .1‬املادة احلادية عشرة من نظام التحكيم‪.‬‬\n                                               ‫‪ .2‬املادة الثامنة من نظام التحكيم‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل ناظــر الوقــف بدعــوى ضــد شــركة (‪ )0000‬بــأن موكلــه‬\n      ‫تعاقــد مــع املدعــي عليهــا علــى توريــد ســتة مصاعــد للفنــدق العائــدة‬\n      ‫للوقــف وألنهــا تأخــرت يف تركيــب املصاعــد وأضــرت بالوقــف حيــث‬\n      ‫قــام املســتأجر بإلغــاء عقــد اســتئجار املبنــى ملوســم حــج ذلــك العــام عليــه‬\n      ‫وألنــه فــوت علــى الوقــف ومســتحقيه منفعــة وألن تفويــت املنفعــة التــي‬\n      ‫انعقــد ســبب وجودهــا يف حكــم تفويــت املنفعــة املتحققــة وألن قواعــد‬\n      ‫الشــرعية تقضــي بأنــه «ال ضــرر وال ضــرار» وألنــه ضــرب مــن ضــروب‬\n\n‫‪187‬‬\n\f‫اإلتــاف وســبب مــن أســباب التعويــض فقــد طالــب مبــا يلــي‪ /1 :‬تعويــض‬\n‫األوقــاف عــن قيمــة عقــد اإلجــارة امللغــى‪ /2 .‬دفــع قيمــة الغرامــة املترتبــة‬\n‫علــى إلغــاء العقــد مــع البعثــة املســتأجرة‪ /3 .‬دفــع الغرامــة املترتبــة علــى‬\n‫تأخيــر تنفيــذ العقــد ‪ -‬دفــع وكيــل املدعــى عليهــا بتمســكه مبــا ورد يف‬\n‫وثيقــة العقــد املبرمــة مــن اللجــوء للتحكيــم حــال النــزاع ‪ -‬طلــب وكيــل‬\n‫الناظــر عــدم االلتفــات ملــا دفــع بــه ألن التحكيــم محصــور يف العقــد‬\n‫بتفســير بنــود العقــد والنــزاع ليــس يف تفســيره أمــا العبــارة األخــرى‬\n‫فقــد اشــترطت قبــل اللجــوء إليــه محاولــة التســوية والصلــح وناظــر‬\n‫الوقــف ال ميكنــه أن يصالــح شــرعا وأن اللجــوء إليــه اختيــاري وواليــة‬\n‫احملكمــة أوســع وأن النــزاع إذا كان متعلقــا بالوقــف فــا واليــة إال‬\n‫للمحاكــم العامــة وأن القاضــي محكــم وزيــادة وأن الغرفــة التجاريــة‬\n‫تنظــر النــزاع بــن املؤسســات والشــركات والوقــف ليــس كذلــك وأن‬\n‫الشــرط اختيــاري وليــس إجباريــا‪ -‬جــرى االطــاع علــى العقــد ورصــد‬\n‫مضمونــه ‪ -‬عليــه وألن املدعــى عليــه دفــع بوجــود شــرط التحكيــم يف‬\n‫العقــد املكتــوب بــن الطرفــن وملصادقــة املدعــي وكالــة علــى ذلــك‬\n‫وبعــد االطــاع علــى وثيقــة العقــد املبــرم بــن الطرفــن وملــا جــاء يف املــادة‬\n‫الثالثــة عشــرة منــه وألن هــذا العقــد بــن الطرفــن عقــد بيــع مصاعــد‬\n‫وتركيبهــا‪ ،‬وبعــد االطــاع علــى نظــام التحكيــم الصــادر باملرســوم‬\n‫امللكــي رقــم م ‪ 34 /‬يف ‪1433/5/24‬ه ـ مبــا يف ذلــك املــادة احلاديــة‬\n‫عشــر ومضمونهــا أنــه يجــب علــى اجلهــة التــي يرفــع إليهــا نــزاع يوجــد‬\n‫يف شــأنه اتفــاق حتكيــم أن حتكــم بعــدم جــواز نظــر الدعــوى إذا دفــع‬\n‫املدعــى عليــه بذلــك قبــل أي طلــب أو دفــاع يف الدعــوى أ‪.‬ه ـ مضمونــه ‪،‬‬\n‫عليــه ولتحققــه يف هــذه القضيــة لدفــع املدعــى عليــه بالتحكيــم قبــل‬\n\n\n                                                                                        ‫‪188‬‬\n\f      ‫أي طلــب دفــاع يف الدعــوى‪ ،‬وأمــا كــون املدعــي ناظــر وقــف فــإن ذلــك‬\n      ‫ال يبطــل شــرط التحكيــم ألن التحكيــم خاضــع لرقابــة احملكمــة‬\n      ‫املختصــة وهــي محكمــة االســتئناف وبإمــكان الناظــر إذا صــدر‬\n      ‫حكــم التحكيــم أن يتقــدم بطعنــه حســب نظــام التحكيــم كمــا‬\n      ‫قــررت ذلــك املــادة الثامنــة مــن النظــام التــي نصــت بــأن االختصــاص‬\n      ‫بنظــر دعــوى بطــان حكــم التحكيــم واملســائل التــي يحيلهــا هــذا‬\n      ‫النظــام للمحكمــة املختصــة بعقــود حملكمــة االســتئناف املختصــة‬\n      ‫أصــا بنظــر النــزاع أ‪.‬ه ـ لذلــك كلــه فقــد حكمــت الدائــرة بعــدم‬\n      ‫جــواز نظــر هــذه الدعــوى‪ -‬قــرر وكيــل الناظــر عــدم القناعــة وأفهــم‬\n                      ‫بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                           ‫مبكــة املكرمــة وبنـ ً‬\n      ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33699557‬واملقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332222814‬وتاريــخ ‪1433/12/22‬ه ـ حضــر (‪).....‬‬\n      ‫بالســجل املدنــي رقــم (‪ ).....‬بوكالتــه عــن (‪ ).....‬بصفتــه ناظــر ًا علــى‬\n      ‫أوقــاف (‪ ).....‬مبوجــب صــك النظــارة الصــادر مــن احملكمــة العامــة‬\n      ‫مبكــة املكرمــة برقــم ‪ 11/31/51‬يف ‪1421/7/21‬ه مبوجب الوكالة‬\n      ‫الصــادرة مــن كتابــة عدل الثانية مبكة املكرمة برقم ‪3453/12657‬‬\n      ‫يف ‪1429/3/2‬ه ـ والتــي تخولــه إقامــة وســماع الدعــاوي واملرافعــة‬\n      ‫واملدافعــة ‪..‬الــخ وادعــى علــى احلاضــر معــه يف مجلــس احلكــم (‪).....‬‬\n      ‫ســجل مدنــي رقــم (‪ ).....‬بوكالتــه عــن (‪ ).....‬يابانــي اجلنســية باإلقامــة‬\n\n‫‪189‬‬\n\f‫رقــم (‪ ).....‬بتاريــخ ‪1428/3/1‬ه ـ بصفتــه املديــر التنفيــذي لشــركة‬\n‫(‪ ).....‬مبوجــب الترخيــص االســتثماري رقــم ‪ 1/1000‬بتاريــخ‬\n‫‪1427/6/27‬ه ـ ومبوجــب الســجل التجــاري رقــم (‪ ).....‬بتاريــخ‬\n‫‪1400/3/11‬ه ـ وذلــك مبوجــب الوكالــة الصــادرة مــن كاتــب عــدل‬\n‫العــدل املكلــف يف الهيئــة العامــة لالســتثمار برقــم ‪ 38/806‬يف‬\n‫‪1428/7/15‬ه ـ والتــي تخولــه إقامــة وســماع الدعــاوي واملرافعــة‬\n‫واملدافعــة والصلــح‪ .‬الــخ ‪ ،‬قائــا يف دعــواه فقــد تعاقــد املدعــي مــع‬\n‫املدعــي عليهــا شــركة (‪ ).....‬مبكــة املكرمــة علــى توريــد عــدد ســتة‬\n‫مصاعــد للفنــدق العائــد للوقــف الكائــن (‪ )...‬مبكــة املكرمــة حســب‬\n‫العقــد املرفــق وحيــث ان الشــركة املذكــورة أخلــت بالتزاماتهــا‬\n‫التعاقديــة بعــدم تنفيــذ العقــد وتأخيرهــا يف تركيــب املصاعــد حســب‬\n‫التاريــخ احملــدد بالعقــد وهــو ‪1433/9/8‬ه ـ وأضــرت الشــركة بالوقــف‬\n‫ضــرر كبيــر ًا حيــث ترتــب علــى تأخيرهــم يف تركيــب املصاعــد حتــى‬\n‫تاريــخ ‪1433/11/12‬ه ـ قيــام البعثــة (‪ ).....‬بإلغــاء العقــد املوقــع معهــم‬\n‫الســتئجار الفنــدق ملوســم حــج عــام ‪1433‬ه ـ مببلــغ وقــدره ســتة مليــون‬\n‫وأربعمائــة وثمانــون ألــف ريــال املرفــق وادى ذلــك الــى تفويــت املنافــع‬\n‫علــى الوقــف ومســتحقيه وحيــث ان تفويــت املنفعــة التــي انعقــد ســبب‬\n‫وجودهــا أصبحــت يف حكــم املنفعــة املتحققــة يترتــب عليــه ضــرر‬\n‫وقواعــد الشــرعية تقضــي انــه ( ال ضــرر وال ضــرار وان الضــرر يــزال )‬\n‫ونظــرا ألن تفويــت املنافــع هــو نــوع مــن انــواع االتــاف واالتــاف ســبب‬\n‫مــن اســباب التعويــض التــي جــاءت االدلــة مــن الكتــاب والســنة‬\n‫مبشــروعيته وهــو املــال الــذي يحكــم بــه علــى مــن تســبب يف عــدم إدراك‬\n‫إنســان مصلحــة أو فائــدة مشــروعة لــه تأكــد حصولهــا فإنــي اطالــب‬\n\n\n                                                                                 ‫‪190‬‬\n\f      ‫املدعــي عليهــا بالتالــي‪ /1 -:‬تعويــض األوقــاف عــن قيمــة عقــد اإلجــارة‬\n      ‫امللغــى والبالــغ قيمتــه ســته مليــون وأربعمائــة وثمانــون ألــف ريــال ‪ /2‬دفــع‬\n      ‫قيمــة الغرامــة املترتبــة علــى الغــاء العقــد مــع البعثــة (‪ ).....‬والبالغــة قيمتها‬\n      ‫(‪ )1.296.600‬ريــال متثــل ‪ %20‬مــن قيمــة العقــد ‪ /3‬دفــع الغرامــة املترتبــة‬\n      ‫على تأخير تنفيذ العقد والبالغ قدرها ســبعة وتســعون ألف وخمســمائة‬\n      ‫ريــال ‪ .‬أ‪.‬ه ـ ‪ ،‬هــذه دعوانــا ‪ ،‬وبســؤال املدعــي عليــه وكالــة عــن دعــوى‬\n      ‫املدعــي وكالــة فقــال إن املــادة الثالثــة عشــر مــن العقــد بــن الطرفــن‬\n      ‫تنــص علــى انــه يف حالــة وجــود خــاف بــن الطرفــن فإنــه تتــم تســويته‬\n      ‫بواســطة التحكيــم ولــذا فــإن الشــركة موكلتــي تتمســك بذلــك‬\n      ‫وتطلــب مــن املدعــي اللجــوء للتحكيــم حســب العقــد ‪ ،‬هكــذا قــرر‪،‬‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة أبــرز ورقــة هــذا نصهــا ‪ -:‬بعــد‬\n      ‫الرجــوع ملوكلــي والتأمــل يف منطــوق العقــد ومــا نصــت عليــه الفقــرة‬\n      ‫رقــم (‪ )13‬مــن نفــس العقــد والتــي تتحــدث عــن ( التحكيــم ) ‪ ،‬وهــي‬\n      ‫نفــس الفقــرة التــي احتــج مبضمونهــا وكيــل املدعــى عليهــا ‪ -‬يف اجللســة‬\n      ‫الســابقة ‪ -‬يف الدفــع بطلــب التحكيــم وفق ـ ًا لنظــم وقوانــن الغرفــة‬\n      ‫التجاريــة والصناعيــة باململكــة العربيــة الســعودية حســب مــا نصــت‬\n      ‫عليــه الفقــرة الســابقة الذكــر ‪ -‬كمــا زعــم‪ ،‬فإنــي أبــن لفضيلتكــم‬\n      ‫مــا يلــي ‪ :‬أو ًال ‪ :‬عــدم صحــة مــا ذكــره وكيــل املدعــى عليهــا يف مــا‬\n      ‫ادعــاه أعــاه لعــدة أســباب‪ -1 :‬إن شــرط التحكيــم كمــا نصــت عليــه‬\n      ‫الفقــرة ســابقة الذكــر ال ينطبــق علــى الدعــوى التــي بــن أيدينــا ؛ فنــص‬\n      ‫الفقــرة ‪ ( :‬مالــم ينــص علــى خــاف ذلــك‪ ،‬فإنــه يف حالــة حــدوث أي‬\n      ‫خــاف حــول تفســير بنــود هــذا العقــد بــن الطرفــن ‪ ، )...‬واخلــاف يف‬\n      ‫هــذه الدعــوى ليــس يف تفســير بنــود العقــد وإمنــا اخلــاف يف عــدم تنفيــذ‬\n\n\n‫‪191‬‬\n\f‫املدعــى عليهــا لبنــود العقــد ‪ ،‬فمحــل اخلــاف هــو مــا ترتــب عليــه مــن‬\n‫تفويــت املنفعــة مــن املدعــى عليهــا واإلضــرار بالوقــف‪ ،‬وليــس خالف ـ ًا‬\n‫يحتمــل العقــد فيــه مــا يحتــاج تفســيره ‪ -2.‬نصــت الفقــرة أن ‪( :‬يحــاول‬\n‫الطرفــان الوصــول إلــى تســوية ســلمية يف أســرع وقــت ممكــن ‪ ،‬ويف‬\n‫حالــة فشــل الطرفــن يف الوصــول إلــى تســوية تتــم تســوية املوضــوع‬\n‫بواســطة التحكيــم ‪ ) ...‬والتســوية هــي ‪ :‬املصاحلــة والتوافــق ‪ ،‬ونحــن‬\n‫هنــا يف هــذه الدعــوى لســنا يف توافــق بــل نحــن يف مشــاحنة ونــزاع ‪ .‬كمــا‬\n‫أن ناظــر الوقــف لــم يلجــأ للتســوية ألنــه ال يســوغ للناظــر التســوية‬\n‫واملصاحلــة ‪ ،‬وكمــا يعلــم فضيلتكــم فــإن العلمــاء رحمهــم اهلل منهــم‬\n‫مــن منــع ناظــر الوقــف مــن املصاحلــة والتســوية ومنهــم مــن أجــازه لكــن‬\n‫بــإذن احلاكــم ؛ ألن الناظــر مطالــب بســلوك الســبيل األمثــل حلصــول‬\n‫املصلحــة والغبطــة للوقــف وليــس التســوية واملصاحلــة ‪ -3.‬إن احملكمــة‬\n‫العامــة هــي املختصــة بالنظــر الوالئــي لقضايــا األوقــاف وليــس لغيرهــا‬\n‫ا عــن أن‬  ‫مــن اجلهــات التحكيميــة أو القضائيــة النظــر فيهــا ‪ ،‬فض ـ ً‬\n‫القاضــي محكــم وزيــادة ‪ ،‬وقــرار التحكيــم مآلــه ومصيــره القضاء‪،‬ال‬\n‫ســيما إذا اختلــف احملكمــان يف اختيــار محكــم مرجــح بينهمــا ‪ ،‬ممــا‬\n‫يكــون فيــه إضــرار بالوقــف وتعطيــل ملصاحلــه ؛ فــكان الرجــوع‬\n‫للحاكــم الشــرعي فيــه حفــظ للوقــف ‪ ،‬وخــروج مــن طائلــة األعبــاء‬\n‫املاليــة التــي قــد يتحملهــا ‪ -4 .‬إن أنظمــة وقوانــن الغرفــة التجاريــة‬\n‫والصناعيــة تختــص بالنظــر يف قضايــا الشــركات واملؤسســات‬\n‫الربحيــة‪ ،‬والوقــف شــخصية اعتباريــة ال ربحيــة ‪ -5 .‬لــو ســلمنا جــد ًال‬\n‫بصحــة شــرط التحكيــم املوجــود يف الفقــرة الســابقة الذكــر‪ ،‬فــإن‬\n‫هــذا الشــرط شــرط جــواز ال شــرط إلــزام‪ -6.‬إن متســك وكيــل املدعــى‬\n\n\n                                                                                   ‫‪192‬‬\n\f      ‫عليهــا بهــذا الشــرط ال يعــدوا أن يكــون نكــو ًال عــن إجابــة الدعــوى ‪،‬‬\n      ‫ال للمماطلــة وإطالــة أمــد القضيــة ‪ ،‬ممــا يزيــد مــن إحلــاق الضــرر‬   ‫وســبي ً‬\n      ‫بالوقــف وتفويــت املنفعــة عليــه ال ســيما أن املؤسســة األهليــة ملطــويف‬\n      ‫حجــاج الــدول العربيــة قــد ربطــت الســماح للوقــف باســتخراج تصريــح‬\n      ‫لتأجيــر العمــارة محــل الدعــوى بدفــع قيمــة الغرامــة املاليــة التــي يطالــب‬\n      ‫بها بعثة احلج (‪ )...‬الوقف ‪ .‬ثاني ًا ‪ :‬نتمســك ببقاء دعوانا لدى فضيلتكم‬\n      ‫ومواصلــة النظــر فيهــا ؛ الختصــاص احملكمــة العامــة مبكــة بالنظــر‬\n      ‫الوالئــي فيهــا ‪ .‬وبعــرض ذلــك علــى املدعى عليه وكالة قال إن الشــركة‬\n      ‫موكلتــي مصــرة علــى التحكيــم ألنــه مشــروط العقــد بــن الطرفــن‬\n      ‫هكــذا قــرر فطلبــت مــن الطرفــن العقــد بينهمــا فأبــرز املدعــي وكالــة‬\n      ‫عقــد ًا هــذا نصــه ‪ -:‬لقــد مت إبــرام هــذا العقــد يف هــذا اليــوم ( بــدون) مــن‬\n      ‫شــهر ( بــدون ) ‪2010‬م بــن كل مــن وقــف (‪ ).....‬وميثلــه يف هــذا العقــد‬\n      ‫املهنــدس (‪ ،).....‬ويقــع عنوانهــا يف مكــة املكرمــة ‪ ،‬اململكــة العربيــة‬\n      ‫الســعودية ‪ ،‬ويشــار إليــه فيمــا بعــد ب ـ ( الطــرف األول ) وشــركة (‪).....‬‬\n      ‫ويقــع عنوانهــا يف ص ‪.‬ب (‪ ).....‬مكــة املكرمــة ‪ ،‬اململكــة العربيــة‬\n      ‫الســعودية ويشــار إليهــا فيمــا بعــد ب ـ ( الطــرف الثانــي ) االتفاقيــة حيــث‬\n      ‫إن الطــرف األول قــد طلــب مــن الطــرف الثانــي توريــد وتركيــب عــدد‬\n      ‫ســتة (‪ )6‬مصعــد ركاب ماركــة (‪ ).....‬مببنــى وقــف (‪ ).....‬مبكــة‬\n      ‫املكرمــة ‪ ،‬اململكــة العربيــة الســعودية‪ .‬وحيــث إن الطــرف الثانــي قــد‬\n      ‫وافــق علــى القيــام بتنفيــذ هــذا العمــل وفقــا لشــروط هــذا العقــد ‪ .‬وعليــه‬\n      ‫فقــد مت االتفــاق علــى مــا يلــي ‪ -1 :‬مجــال العمــل ‪ :‬توريــد عــدد ســتة (‪)6‬‬\n      ‫مصعــد ركاب ماركــة (‪ ، ).....‬مــن شــركة (‪ ،).....‬مبــا يف ذلــك‬\n      ‫التركيــب والصيانــة املجانيــة ملــدة ســنة واحــدة (‪ -2 ، )1‬قيمــة العقــد ‪:‬‬\n\n\n‫‪193‬‬\n\f‫تبلــغ قيمــة هــذا العقــد مبلغــا وقــدره ‪ 1.950.000‬ريــال ( فقــط واحــد‬\n‫مليــون وتســعمائة وخمســون ألــف ريــال ســعودي ال غيــر ) ‪ .‬يشــمل الســعر‬\n‫املبــن أعــاه الرســوم اجلمركيــة والضرائــب والنقــل الداخلــي والتأمــن‬\n‫‪ -3 .‬شــروط الدفــع ‪ :‬أ ‪ /‬مبلــغ ‪ 682.500‬ريــال ( فقــط ســتمائة واثنــان‬\n‫وثمانــون ألــف وخمســمائة ريــال ســعودي ال غيــر ) والــذي ميثــل خمســة‬\n‫وثالثــن باملائــة (‪ ) %35‬مــن قيمــة العقــد يتــم دفعــه للطــرف الثانــي عنــد‬\n‫توقيــع العقــد‪ .‬ب‪ /‬مبلــغ (‪ )682.500‬ريــال ( فقــط ســتمائة واثنــان‬\n‫وثمانــون ألــف وخمســمائة ريــال ســعودي ال غيــر ) والــذي ميثــل خمســة‬\n‫وثالثــن باملائــة ( ‪ ) %35‬مــن قيمــة العقــد يتــم دفعــه للطــرف الثانــي خــال‬\n‫ســبعة (‪ )7‬أيــام بعــد وصــول املعــدات ملوقــع العمــل‪ .‬ج‪ /‬مبلــغ ‪390.000‬‬\n‫ريــال ( فقــط ثالثمائــة وتســعون ألــف ريــال ســعودي ال غيــر ) والــذي ميثــل‬\n‫عشــرين باملائــة (‪ )% 20‬مــن قيمــة العقــد يتــم دفعــه للطــرف الثانــي خــال‬\n‫ســبعة (‪ )7‬أيــام بعــد االنتهــاء مــن أعمــال التركيــب‪ .‬د‪ /‬مبلــغ ‪195.000‬‬\n‫ريــال (فقــط مائــة وخمســة وتســعون الــف ريــال ســعودي ال غيــر) والــذي‬\n‫ميثــل عشــرة باملائــة (‪ )%10‬مــن قيمــة العقــد يتــم دفعــه للطــرف الثانــي‬\n‫عنــد الفــراغ مــن أعمــال الضبــط‪ /‬االختبــار التشــغيلي وجتهيــز املعــدات‬\n‫لتســليمها للطــرف األول‪ 4 .‬ـ املواصفــات ‪( :‬فضــا أنظــر امللحــق «أ»‬\n‫املرفــق) ‪ 5‬ـ املــواد املعــدات واألعمــال التــي يلتــزم بهــا الطــرف األول ‪:‬‬\n‫(فضــا أنظــر امللحــق «ب» املرفــق) ‪ 6‬ـ إكمــال األعمــال ‪ :‬أ ) يتــم شــحن‬\n‫املعــدات وتســليمها باملوقــع يف غضــون ســبعة (‪ )7‬شــهور مــن تاريــخ‬\n‫اســتالم الدفعــة املقدمــة املبينــة يف الفقــرة (‪ 3‬ــأ) يف شــروط الدفــع أعــاه‬\n‫والبالــغ قدرهــا (‪ )682.500‬ريــال (فقــط ســتمائة واثنــان وثمانــون الــف‬\n‫وخمســمائة ريــال ســعودي ال غيــر) واملوافقــة النهائيــة علــى املخططــات‬\n\n\n                                                                                     ‫‪194‬‬\n\f      ‫واملواصفــات أيهمــا يأتــي الحقــا ‪ .‬بعــد وصــول مــواد املصاعــد‪ ،‬فــإذا‬\n      ‫رفــض صاحــب العمــل اســتالم مــواد مصاعــده وحفظهــا مبوقعــه خــال‬\n      ‫أســبوع من تاريخ أخطاره ‪ ،‬فانه ســيتحمل قيمة رســوم أرضية املســتودع‬\n      ‫التــي يتكبدهــا وكيــل الشــحن طــوال مــدة بقائهــا باملســتودع ‪ .‬ب) يتــم‬\n      ‫تركيــب املعــدات وإجــراء االختبــارات التشــغيلية عليهــا خــال أربعــة‬\n      ‫(‪)4‬شــهور بعــد اســتالم الدفعــة املبينــة يف الفقــرة (‪3‬ـ ب) وذلــك وفقـ ًا ملــا‬\n      ‫يلــي ‪ )I :‬التركيــب ‪ :‬وافــق الطــرف األول علــى جتهيــز وتســليم بئــر‬\n      ‫املصاعــد مركبـ ًا يف داخلــه الســقائل والكمــرات الفاصلــة وزوايــا دعــم‬\n      ‫العتــب للطــرف الثانــي قبــل خمســة عشــر (‪(15‬يوم ـ ًا علــى األقــل مــن‬\n      ‫تاريــخ وصــول املعــدات ملوقــع العمــل وذلــك لتجنــب عرقلــة أعمــال‬\n      ‫التركيــب ‪ .‬ب) مــن أجــل احلفــاظ علــى ســامة العمالــة واملــواد فقد وافق‬\n      ‫الطــرف األول علــى عــدم قيامــه بــأي أعمــال أخــرى داخــل البئــر بعــد‬\n      ‫تســليمه للطــرف الثانــي أو داخــل احلفــرة أو غرفــة املاكينــة إال بعــد‬\n      ‫احلصــول علــى موافقــة الطــرف الثانــي والتنســيق معــه بهــذا اخلصــوص‪.‬‬\n      ‫ج) اســتالم مبلــغ وقــدره ‪ 682.500‬ريــال وفقـ ًا للفقــرة (‪3‬ـ ب ) ‪ .‬د ) يلتــزم‬\n      ‫الطــرف األول بإكمــال األعمــال حســبما هــو مبــن يف امللحــق «ب» ‪)II‬‬\n      ‫االختيــار التشــغيلي ‪ :‬أ ) اســتالم مبلــغ وقــدره ‪ 390.000‬ريــال وفق ـ ًا‬\n      ‫للفقرة (‪3‬ـ ج)‪ .‬ب) توفير الطاقة الكهربائية املســتدمية باملوقع بواســطة‬\n      ‫الطــرف األول ‪ ) III .‬التســليم ‪ :‬يتــم تســليم الســتة (‪ )6‬مصاعــد مباشــرة‬\n      ‫بعــد اســتالم الدفعــة املبينــة يف الفقــرة ( ‪3‬ـ د) ‪ -7 .‬تقــدمي واعتمــاد‬\n      ‫املخططــات الهندســية للطــرف األول بغــرض اعتمادهــا خــال أســبوعني‬\n      ‫(‪ )2‬بعــد توقيــع العقــد وعلــى الطــرف األول مراجعــة واعتماد املخططات‬\n      ‫واملواصفــات والتشــطيب خــال أســبوع واحــد (‪ )1‬مــن تقدميهــا بواســطة‬\n\n\n‫‪195‬‬\n\f‫الطــرف الثانــي ‪ -8.‬الصيانــة والضمــان ‪ :‬يتــم ضمــان املعــدات التــي يتــم‬\n‫توريدهــا مبوجــب هــذا العقــد مــن أعطــال التصميــم وخلــل املصنعيــة ملــدة‬\n‫اثنــي عشــر (‪ )12‬شــهر ًا مــن تاريــخ التســليم أو ثمانيــة عشــر (‪ )18‬شــهر ًا‬\n‫مــن تاريــخ الشــحن أيهمــا يأتــي أوال ‪ .‬يلتــزم الطــرف الثانــي خــال هــذه‬\n‫الفتــرة بتقــدمي الصيانــة الوقائية الشــهرية واالســتجابة لنــداءات الطوارئ‬\n‫باملجــان وعلــى حســاب الطــرف الثانــي ‪ -9 .‬غرامــة التأخيــر ‪ :‬يف حالــة‬\n‫حــدوث تأخيــر ألســباب تتعلــق بالطــرف الثانــي وحــده يلتــزم الطــرف‬\n‫الثانــي بدفــع غرامــة تأخيــر مبقــدار (‪ )%1‬مــن قيمــة العقــد لــكل أســبوع‬\n‫تأخيــر بحيــث ال تتعــدى القيمــة اإلجماليــة للغرامــة (‪ )%5‬مــن قيمــة العقد‬\n‫وعلــى أيــة حــال ‪ ،‬فــإذا حــدث تأخيــر جلــزء مــن العمــل واجلــزء املتأخــر ال‬\n‫يحــول دون اســتخدام اجلــزء الــذي مت تنفيــذه ‪ ،‬ففــي هــذه احلالــة يجــب أال‬\n‫تتعــدى الغرامــة اإلجماليــة (‪ )%5‬مــن قيمــة اجلــزء املتأخــر ‪ / .‬القــوة‬\n‫القاهــرة ‪ :‬لــن يكــون الطــرف الثانــي مســئوال لــدى الطــرف األول يف‬\n‫حالــة الظــروف االضطراريــة والقــوة القاهــرة التــي ال ميكــن توقعهــا‬\n‫وجتنبهــا لكونهــا خارجــة عــن اإلرادة وهــي علــى ســبيل املثــال ال احلصــر‬\n‫‪ ،‬احلــرب وحــاالت احلــرب ‪ ،‬األحــداث العدائيــة ‪ ،‬احلضــر التجــاري‪،‬‬\n‫األوبئــة والثــورات واإلضرابــات العامــة الــخ ‪ ،‬والتــي متنــع الطــرف الثانــي‬\n‫مــن الوفــاء بالتزاماتــه جتــاه العقــد ‪ -11 .‬نقــل امللكيــة ‪ :‬يف حالــة حتويــل‬\n‫ونقــل ملكيــة املبانــي موضــوع هــذا العقــد لطــرف ثالــث وألي ســبب مــن‬\n‫األســباب يظــل الطــرف األول مســئوال لــدى الطــرف الثانــي وفقـ ًا لبنــود‬\n‫هــذه االتفاقيــة ‪ -12 .‬التغييــرات واإلضافــة ‪ /‬احلــذف ‪ :‬عنــد اتفــاق‬\n‫الطرفــن املوقعــن علــى هــذا العقــد أو مــن يفوضانــه ‪ ،‬ميكــن إجــراء‬\n‫تغييــر أو إضافــة أو حــذف يف مجــال األعمــال ال يتــم إجــراء مثــل هــذه‬\n\n\n                                                                                      ‫‪196‬‬\n\f      ‫التغييــرات إال بعــد إصــدار أمــر تغييــر معتمــد وموقــع مــن كال الطرفــن‬\n      ‫يتــم فيــه بيــان مجــال األعمــال املعدلــة وتغييــر التكلفــة وقيمــة العقــد‬\n      ‫املعدلــة وكذلــك اجلــدول املعدل لفترة إكمال األعمال‪ -13 .‬التحكيم‬\n      ‫‪ :‬مالــم ينــص علــى خــاف ذلــك ‪ ،‬فإنــه يف حالــة حــدوث أي خــاف حــول‬\n      ‫تفســير بنــود هــذا العقــد بــن الطرفــن‪ ،‬يحــاول الطرفــان الوصــول إلــى‬\n      ‫تســوية ســلمية بأســرع وقــت ممكــن‪ ،‬ويف حالــة فشــل الطرفــن يف‬\n      ‫الوصــول إلــى تســوية تتــم تســوية املوضــوع بواســطة التحكيــم والــذي‬\n      ‫يتــم عقــده وفقـ ًا لنظــم وقوانــن الغرفــة التجاريــة والصناعيــة باململكــة‬\n      ‫العربيــة الســعودية ويكــون مقــر التحكيــم مبدينــة مكــة املكرمــة ‪.‬‬\n      ‫وإشــهادا علــى مــا تقــدم ‪ ،‬فقــد قــام الطرفــان بتوقيــع هــذا العقــد‬\n      ‫واعتمــاده وفق ـ ًا للتاريــخ املوضــح أدنــاه ‪ .‬الطــرف األول ‪ :‬وقــف (‪).....‬‬\n      ‫وميثلــه ‪ :‬املهنــدس (‪ ).....‬التوقيــع‪ :‬التاريــخ ‪ :‬الطــرف الثانــي ‪ :‬شــركة‬\n      ‫(‪ ).....‬املهنــدس (‪ ).....‬نائــب الرئيــس أه ـ ‪ ،‬وبعــرض هــذا العقــد علــى‬\n      ‫املدعــى عليــه وكالــة صــادق عليــه ثــم جــرى اطالعــي على صــك النظارة‬\n      ‫الصــادر مــن هــذه احملكمــة برقــم ‪ 51/31/11‬يف ‪1421/7/21‬ه ـ‬\n      ‫فوجدتــه يتضمــن إقامــة (‪ )...‬ناظــرا علــى أوقــاف (‪ ).....‬املذكــور باطنــه‬\n      ‫فبنــاء علــى مــا تقــدم وبعــد ســماع دعــوى املدعــي وألن املدعــى عليــه دفــع‬\n      ‫بوجــود شــرط التحكيــم يف العقــد املكتــوب بــن الطرفــن ومصادقــة‬\n      ‫املدعــي وكالــة علــى ذلــك وبعــد االطــاع علــى العقــد بــن الطرفــن‬\n      ‫والــذي جــاء يف املــادة الثالثــة عشــر منــه مــا نصــه ( إنــه يف حالــة حــدوث‬\n      ‫أي خــاف حــول تفســير بنــود هــذا العقــد بــن الطرفــن ‪ ،‬يحــاول‬\n      ‫الطرفــان الوصــول إلــى تســوية ســلمية بأســرع وقــت ممكــن ‪ ،‬ويف حالــة‬\n      ‫فشــل الطرفــن يف الوصــول إلــى تســوية تتــم تســوية املوضــوع بواســطة‬\n\n\n‫‪197‬‬\n\f‫التحكيــم والــذي يتــم عقــده وفق ـ ًا لنظــم وقوانــن الغرفــة التجاريــة‬\n‫والصناعيــة باململكــة العربيــة الســعودية ويكــون مقــر التحكيــم‬\n‫مبدينــة مكــة املكرمــة) وألن هــذا العقــد بــن الطرفــن هــو عقــد بيــع‬\n‫مصاعــد وتركيبهــا وبعــد االطــاع علــى نظــام التحكيــم الصــادر‬\n‫باملرســوم امللكــي رقــم م ‪ 34 /‬يف ‪1433/5/24‬ه ـ مبــا يف ذلــك املــادة‬\n‫احلاديــة عشــر والتــي نصــت علــى أنــه يجــب علــى اجلهــة التــي يرفــع إليهــا‬\n‫نــزاع يوجــد يف شــأنه اتفــاق حتكيــم أن حتكــم بعــدم جــواز نظــر‬\n‫الدعــوى إذا دفــع املدعــى عليــه بذلــك قبــل أي طلــب أو دفــاع يف الدعــوى‬\n‫أه ـ وألن ذلــك حتقــق فيهــذه القضيــة فقــد دفــع املدعــى عليــه بالتحكيــم‬\n‫قبــل أي طلــب دفــاع يف الدعــوى كمــا أن كــون املدعــي ناظــر وقــف فــإن‬\n‫ذلــك ال يبطــل شــرط التحكيــم ألن التحكيــم خاضــع لرقابة احملكمة‬\n‫املختصــة وهــي محكمــة االســتئناف وبإمــكان الناظــر إذا صــدر‬\n‫حكــم التحكيــم أن يتقــدم بطعنــه حســب نظــام التحكيــم كمــا‬\n‫قــررت ذلــك املــادة الثامنــة مــن النظــام التــي نصــت بــأن االختصــاص‬\n‫بنظــر دعــوى بطــان حكــم التحكيــم واملســائل التــي يحيلهــا هــذا‬\n‫النظــام للمحكمــة املختصــة بعقــود حملكمــة االســتئناف املختصــة‬\n‫أصــا بنظــر النــزاع أه ـ لذلــك كلــه فقــد حكمــت بعــدم جــواز نظــر‬\n‫هــذه الدعــوى وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه وكاله‬\n‫القناعــة وقــرر املدعــي وكالــة عــدم القناعــة وطلــب رفعــه حملكمــة‬\n‫االســتئناف بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه مبراجعــة‬\n‫احملكمــة خــال عشــرة أيــام الســتالم الصــك وتقــدمي الالئحــة‬\n‫االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــر عــن تقــدمي‬\n‫الئحتــه وألن احلكــم علــى ناظر وقف فســيتم رفعه حملكمة االســتئناف‬\n\n\n                                                                                      ‫‪198‬‬\n\f      ‫بنــاء علــى املــادة ‪ 179‬مــن نظــام املرافعــات‪ ،‬وبــاهلل التوفيــق وصلــى اهلل‬\n            ‫على نبينا محمد وعلى آله وصحبه وسلم حرر يف ‪1434/01/20‬ه‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بشــرح فضيلــة الرئيــس رقــم ‪ 34/579675‬يف ‪1434/3/7‬ه ـ علــى‬\n      ‫خطــاب فضيلــة رئيــس محكمــة االســتئناف رقــم ‪ 34287116‬يف‬\n      ‫‪1434/2/17‬ه ـ وقــد صــدر قــرار املالحظــة رقــم ‪ 3451319‬يف‬\n      ‫‪1434/3/1‬ه ـ وهــذا نــص احلاجــة منــه وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا‬\n      ‫يلــي ‪ -1‬إرفــاق صــورة مــن العقــد املبــرم بــن املدعــي واملدعــى عليــه ‪-2‬‬\n      ‫إكمــال الفــراغ بالســطر اخلامــس عشــر بالصفحــة الثانيــة مــن صــك‬\n      ‫احلكــم بذكــر اليــوم والشــهر إن وجــد فــإن لــم يوجــد فيكتــب عبــارة (‬\n      ‫بــدون ) وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم وعليــه أجيــب علــى قــرار أصحــاب الفضيلــة بأنــه جــرى إرفــاق‬\n      ‫صــورة مــن التصديــق الطرفــن كمــا مت إكمــال الــازم حيــال امللحوظة‬\n      ‫الثانيــة وأمــرت برفعــه حملكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/3/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بشــرح فضيلــة الرئيــس رقــم ‪ 34793655‬يف ‪1434/4/13‬ه ـ علــى‬\n      ‫خطــاب فضيلــة رئيــس محكمــة االســتئناف رقــم ‪ 34793655‬يف‬\n      ‫‪1434/4/8‬ه ـ وقــد صــدر قــرار التصديــق رقــم ‪ 34179473‬يف‬\n      ‫‪1434/4/6‬ه ـ وهــذا نصــه احلمــد هلل وحــده والصــاة والســام علــى مــن‬\n      ‫ال نبــي بعــده وبعــد فقــد جــرى منــا نحن قضاة الدائــرة احلقوقية الثانية يف‬\n      ‫محكمــة االســتئناف يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة‬\n\n\n‫‪199‬‬\n\f‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪ 34579675‬وتاريــخ ‪1434/1/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ (‪ ).....‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة‬\n‫برقــم ‪ 3419952‬وتاريــخ ‪1434/1/21‬ه ـ واملتضمــن دعــوى (‪ ).....‬ضــد‬\n‫شــركة (‪ ).....‬وبدارســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف (‪).....‬‬\n‫ختــم وتوقيــع قاضــي اســتئناف (‪ ).....‬ختــم وتوقيــع رئيــس الدائــرة (‪).....‬‬\n‫ختــم وتوقيــع أه ـ وأمــرت بإحلــاق هــذا بضبــط القضيــة حســب التعليمــات‬\n‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1434/4/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34579675‬وتاريــخ‬\n‫‪1434/3/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3419952‬وتاريــخ‬\n‫‪1434/1/21‬ه ـ ‪ ،‬املتضمــن دعــوى (‪ ).....‬ضــد شــركة (‪ ،).....‬وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقرر املوافقــة على احلكم‬\n‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                    ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪200‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":187,"source_page_end":200,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a3f1e438520236d8ba93ccbd4dfc3287831448534453ea258a6fe498957808ce","normalized_text_hash":"226d4cd4fa5b8961d051872110a11d9bae2c620f6ee6e5ae614f7b610a9ee5aa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p187-3419952"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"70b85827-f60e-5dd3-abfa-32df82b12068","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -عقار -تداخل عقارات -كل إثبات إنهائي خالف األصول اإلجرائية أو املوضوعية ال يصح حملة على الصحة ولزم رفعة إلى محكمة الاستئناف -حجة املدعي هو صكه وصكه متفرع عن حجة استحكام مخالفة لألصول اإلجرائية -إذا رفعت املعارضة بعد خروج حجة االستحكام ومصدر احلجة يف المحكمة نفسها فتحال إليه أو إلى خلفه -صرف النظر لعدم االختصاص .","document_number":"33122571","case_number":"32538467","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/8","year":"1434","subject":"اختصاص -عقار -تداخل عقارات -كل إثبات إنهائي خالف األصول اإلجرائية أو املوضوعية ال يصح حملة على الصحة ولزم رفعة إلى محكمة الاستئناف -حجة املدعي هو صكه وصكه متفرع عن حجة استحكام مخالفة لألصول اإلجرائية -إذا رفعت املعارضة بعد خروج حجة االستحكام ومصدر احلجة يف المحكمة نفسها فتحال إليه أو إلى خلفه -صرف النظر لعدم االختصاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 33122571 :‬تاريخه‪1433/3/8 :‬هـ‬\n                   ‫رقم الدعوى‪32538467 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34279180‬تاريخه‪1434/7/25 :‬هـ‬\n\n\n‫اختصــاص ‪ -‬عقــار ‪ -‬تداخــل عقــارات ‪ -‬كل إثبــات إنهائــي خالــف‬\n‫األصــول اإلجرائيــة أو املوضوعيــة ال يصــح حملــة علــى الصحــة ولــزم‬\n‫رفعــة إلــى محكمــة االســتئناف ‪ -‬حجــة املدعــي هــو صكــه وصكــه‬\n‫متفــرع عــن حجــة اســتحكام مخالفــة لألصــول اإلجرائيــة ‪ -‬إذا رفعــت‬\n‫املعارضــة بعــد خــروج حجــة االســتحكام ومصــدر احلجــة يف احملكمــة‬\n‫نفســها فتحــال إليــه أو إلــى خلفــه ‪ -‬صــرف النظــر لعــدم االختصــاص ‪.‬‬\n\n\n\n\n   ‫املادة احلادية واخلمسني بعد املائتني من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اعتــدى علــى جــزء مــن ملكــه‬\n‫الواقــع يف ‪ ....‬اململــوك لــه مبوجــب الصــك الصــادر مــن كاتــب عــدل‬\n‫ينبــع وقــد اعتــدى املدعــى عليــه علــى اجلــزء اجلنوبــي منــه ويطلــب احلكــم‬\n‫علــى املدعــى عليــه برفــع يــده ‪ -‬أجــاب املدعــى عليــه بأنــه يعــارض يف‬\n‫صــك املدعــي ألن الصــك مــزور علــى املوقــع فهــو مطبــق علــى غيــر موقعــه‬\n‫األصلــي وعلــى مقبــرة مــن مقابــر املســلمني القدميــة ولديــه األدلــة املثبتــة‬\n‫علــى ذلــك حيــث إن أســاس صــك املدعــي مبنــي علــى حجــة االســتحكام‬\n‫رقــم ‪ 249‬وقــد طبــق هــذا الصــك علــى تلــك األرض بــدون وجــه حــق‬\n\n                                                                                       ‫‪130‬‬\n\f      ‫وأنــه لــم يعتــد علــى ملــك للمدعــي ألن حجــة االســتحكام ال تقــع يف‬\n      ‫هــذا املوقــع لعــدة أمــور وارده يف نفــس نــص الصــك جــرى بيانهــا ‪ -‬مبــا‬\n      ‫أن صــك املدعــي صــك إفــراغ متفــرع أساس ـ ًا مــن حجــة االســتحكام‬\n      ‫رقــم ‪ 249‬جــرى االطــاع علــى صــك حجــة االســتحكام وقــد تضمــن‬\n      ‫معارضــة البلديــة وصــرف النظــر عــن معارضتهــا ولــم يبعــث إلــى‬\n      ‫محكمــة االســتئناف ومبــا أن حجــة االســتحكام املذكــورة حتتــاج‬\n      ‫تتبــع وتقصــي وهــل تنطبــق علــى املوقــع ذرعـ ًا وحــدود ًا ‪ -‬ملــا تقــدم صــدر‬\n      ‫احلكــم بصــرف النظــر لعــدم االختصــاص ألن حجــة املدعــي هــو صكــه‬\n      ‫وصكــه متفــرع عــن حجــة اســتحكام مخالفــة لألصــول اإلجرائيــة‬\n      ‫وناظــر القضيــة ليــس خلف ـ ًا ملصــدر حجــة االســتحكام ‪ -‬اعتــرض‬\n      ‫الطرفــان علــى احلكــم بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                    ‫اخلامســة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬‫وبنـ ً‬\n      ‫بينبع‪/‬املســاعد برقــم ‪ 32538467‬وتاريــخ ‪ 1432/11/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 321436968‬وتاريــخ ‪ 1432/11/13‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/02/09‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 53‬‬\n      ‫وباالطــاع علــى الصــك رقــم ‪ 249‬يف ‪97/9/14‬هـ جرى إعادتها للرئيس‬\n      ‫لعــدم االختصــاص ثــم أعيــدت لنــا مــن فضيلــة رئيــس احملكمــة بينبــع‬\n      ‫املســاعد برقــم ‪ 321436968‬يف ‪1433/2/1‬ه ـ وســبب هــذه املعاملــة أنــه‬\n      ‫تقــدم‪ .....‬بدعــوى ضــد ‪.....‬ويذكــر فيهــا أن املدعــى عليــه تعــدى علــى‬\n\n‫‪131‬‬\n\f‫جــزء مــن أرضــه اململوكــة لــه بصــك اإلفــراغ رقــم ‪ 516‬بتاريــخ‬\n‫‪1403/3/27‬ه ـ الصــادر مــن كاتــب عــدل ينبــع وهــو جــزء مفــرغ مــن‬\n‫حجــة االســتحكام الصــادرة مــن محكمــة ينبــع مــن قبل رئيســها ســابقا‬\n‫فضيلــة الشــيخ ‪.....‬رحمــه اهلل رقــم ‪ 249‬يف ‪1397/9/14‬ه ـ وباالطــاع‬\n‫علــى صــورة ذلــك الصــك وجــدت فيهــا قوله وصرفت النظــر عن معارضة‬\n‫البلديــة وأمــرت بإخــراج صــك وبعثــه إلــى محكمــة التميــز ولكنــه لــم‬\n‫يبعــث إلــى محكمــة التمييــز وســألت املســؤول عــن الســجل فقــال فعــا‬\n‫لــم يبعــث إلــى محكمــة التمييــز فظهــر لــي أن ذلــك الصــك أوال إفراغــه‬\n‫يف غيــر محلــه فهــو صــك لــم تنتهــي إجراءاتــه ولــم يكتســب القطعيــة‬\n‫فالنظــر فيــه ليــس مــن اختصاصــي وال املعارضــة فيــه بــل مــن اختصــاص‬\n‫رئيــس احملكمــة أو خلفــه لــذا حكمــت بصــرف النظــر عــن الســير يف‬\n‫القضيــة وذلــك مبوجــب املــادة رقــم ‪ 251‬وأمــرت بإرســال هــذا القــرار‬\n‫إلــى محكمــة االســتئناف مبكــة للنظــر يف مثــل هــذه احلــاالت ففــي يــوم‬\n‫الســبت املوافــق‪ 1433/05/22‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 50‬ثــم‬\n‫أعيــدت لنــا املعاملــة مبوجــب خطــاب محكمــة االســتئناف مبكــة‬\n‫املكرمــة برقــم ‪ ...........‬يف ‪1433/3/26‬ه ـ املرفــق بهــا قــرار املالحظــة‬\n‫رقــم ‪ .............‬يف ‪1433/3/22‬ه ـ وهــذا نصــه وبدراســة احلكــم وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة اعادتهــا لفضيلــة‬\n‫ناظرهــا ملالحظــة ان صــرف النظــر عــن الســير يف القضيــة يف غيــر‬\n‫محلــه بــل يتعــن علــى فضيلتــه ســماع دعــوى املدعــي وإجابــة املدعــى‬\n‫عليــه ثــم إجــراء املقتضــى الشــرعي بعــد ذلــك واهلل املوفــق قاضــي‬\n‫اســتئناف ‪.....‬قاضــي اســتئناف ‪.....‬ولــه وجهــة نظــر رئيــس الدائــرة ‪.....‬‬\n‫وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه ثــم أدعــى املدعــي‬\n\n\n                                                                                 ‫‪132‬‬\n\f      ‫‪.....‬قائــا ادعــي علــى احلاضــر معــي باملجلــس الشــرعي ‪.....‬الــذي أعتــدى‬\n      ‫علــى جــزء مــن ملكــي الواقــع يف ج‪ 12‬أذ أملــك ذلــك املوقــع مبوجــب‬\n      ‫الصــك رقــم ‪ ....‬يف ‪1403/3/27‬ه ـ الصــادر مــن كاتــب عــدل ينبــع‬\n      ‫وحــدوده كمــا يلــي مــن الشــمال شــارع مقتــرح مــن قبــل البلديــة وقــد نفــذ‬\n      ‫بطــول‪101،5‬م ومــن الشــرق بطــول ‪ 141،80‬م ويحــده طريــق ومــن‬\n      ‫الغــرب بطــول ‪ 96،45‬م ويحــده ملــك الغيــر ومــن اجلنــوب باقــي صــك‬\n      ‫حجــة االســتحكام االساســية وبطــول ‪100‬م وقــد أعتــدى املدعــى عليــه‬\n      ‫علــى اجلــزء اجلنوبــي ويحــده مــن الشــرق الطريــق بطــول ‪11‬م ومن الشــمال‬\n      ‫ملكــي بطــول ‪50‬م تقريبــا ومــن اجلنــوب بطــول ‪50‬م ويحــده بقيــة الصــك‬\n      ‫االساســي بطــول ‪50‬م ومــن الغــرب بطــول متــرا واحــدا ويحــده ملكــي‬\n      ‫واالعتــداء عبــارة عــن مثلــث امــا االعتــداء عبــارة عــن كشــط ذلــك اجلــزء‬\n      ‫املــردوم ســابقا واطلــب احلكــم علــى املدعــى عليــه برفــع يــده ورد التــراب‬\n      ‫كذلــك حظــر لــدي يف مكتبــي وهددنــي بوظيفتــه وتشــكيكه يف‬\n      ‫صكــي الــذي أمتلــك بــه تلــك االرض وقــال ان صكــي عائــم وانــه مــن‬\n      ‫صكــوك ‪ .....‬وقــد عــرض علــي شــراء صكــه لــذا اطلــب مجازاتــه ورفــع‬\n      ‫الضــرر عــن أرضــي وأســأله اجلــواب وبعــرض الدعــوى املرصــودة بعاليــة‬\n      ‫علــى املدعــى عليــه طلــب اإلمهــال يف اجلــواب وأعطــي جلســة علــى ذلــك‬\n      ‫يف يــوم الســبت ‪1433/6/21‬ه ـ الســاعة التاســعة صباحــا ففــي يــوم‬\n      ‫الســبت املوافــق‪ 1433/06/21‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 58‬‬\n      ‫وفيهــا حضــر املدعــي ‪.....‬وحضــر حلضــوره املدعــى عليــه ‪.....‬ثــم أجــاب‬\n      ‫املدعــى عليــه قائــا اننــي اعــارض يف صــك املدعــي هــذا الصــك املــزور‬\n      ‫علــى املوقــع والطائــر فهــو مطبــق علــى غيــر موقعــه االصلــي وعلــى مقبــره‬\n      ‫مــن مقابــر املســلمني القدميــة ولــدي االدلــة املثبتــة علــى ذلــك حيــث ان‬\n\n\n‫‪133‬‬\n\f‫اســاس صكــه مبنــي علــى حجــة االســتحكام رقــم ‪ 249‬وهــذه احلجــة‬\n‫مــن حجــج ‪.....‬رحمــه اهلل وباســم‪.....‬وتقع شــرق ينبــع طريــق ينبــع النخــل‬\n‫شــمال االزفلــت وصــك جــاره الــذي يحــده مــن الشــرق ‪.....‬صــادر مــن‬\n‫محكمــة ينبــع برقــم ‪ 238‬وتاريــخ ‪1397/5/20‬ه ـ خيــر دليــل علــى‬\n‫كالمــي ويبعــد موقعهمــا أكثــر مــن عشــرين كيــا عــن موقــع النــزاع‬\n‫وقــد طبــق هــذا الصــك علــى تلــك االرض بــدون وجــه حــق أمــا صكــي‬\n‫وطــول ضلــع الشــمالي مائــة متــر ويحــده حــوش ملــك ‪.....‬وهــو الــذي طبــق‬\n‫عليــه حجــة الســتحكام الطائــرة ثــم أفــرغ ‪ .....‬وطــول الضلــع اجلنوبــي‬\n‫مائــة متــر ويحــده شــارع ثــم مخطــط ســعيد عــوده الرفاعــي وطــول الضلــع‬\n‫الشــرقي ســتون متــرا ويحــده الشــارع ثــم ملــك ‪ ........‬وطــول الضلــع‬\n‫الغربــي ســتون متــرا ويحــده شــارع ثــم أرض فضــاء واننــي لــم اعتــد علــى‬\n‫ملــك للمدعــي الن حجــة الســتحكام ال تقــع يف هــذا املوقــع لعــدة أمــور‬\n‫وارده يف نفــس نــص الصــك حيــث جــاء فيهــا انهــا شــرق العصيلــي‬\n‫ضواحــي ينبــع وعندمــا افرغــت االرض للمشــتري ‪ .....‬قــال وكيــل البائــع‬\n‫انهــا تقــع بالعصيلــي بينبــع البحــر ثانيــا ان االرض الصــادر عليهــا حجــة‬\n‫االســتحكام يوجــد بهــا مقبــرة ويقــال انهــا منــذ ‪1344‬ه ـ وقــد بــدأت‬\n‫البلديــة يف تســويرها ثالثــا ان البلديــة ســبق وان اعترضــت علــى حجــة‬\n‫االســتحكام مبوجــب خطابهــا رقــم ‪ 857/835‬يف ‪1397/2/27‬ه ـ ولــم‬\n‫يجــر الوجــه الشــرعي نحــو اعتراضهــا إن املوقــع املذكــور يحــده‬\n‫مخططــات مملوكــه بصكــوك شــرعية ومبنــي بهــا عــدة عمائــر وال‬\n‫توجــد ارض لتلــك احلجــة إن املوقــع املذكــور كان بــه حــوش ملــك ‪.....‬‬\n‫واطــوال اضالعــه خمســة وخمســن متــرا يف مائــة واربعــة وســبعون متــرا‬\n‫وكان عائــق دون تطبيــق حجــة االســتحكام ومت االتفــاق مــع صاحبــه‬\n\n\n                                                                                  ‫‪134‬‬\n\f      ‫بــأن تكــون أطوالــه مائــة يف مئتــان ثــم يفــرغ مــن حجــة االســتحكام‬\n      ‫املطبقــة عليــه وكأن احلــوش لــم يكــن موجــود ًا مــن الســابق إلــى غيــر‬\n      ‫ذلــك مــن التناقضــات الــواردة يف الصــك وخالصــة األمــر أننــي أعــارض‬\n      ‫يف هــذا الصــك الــذي حجتــه لــم تكتســب القطعيــة فهــو ليــس عندنــا‬\n      ‫ولــم تعتــد علــى ملــك للمدعــي وبالرجــوع إلــى حجــة االســتحكام‬\n      ‫وتطبيقهــا بحضــور شــهود األصــل تتضــح الرؤيــا واحلقيقــة وقــال هــذا‬\n      ‫جوابــي وعليــه أوقــع وبعــرض ذلــك علــى املدعــي قــال أطلــب نســخة مــن‬\n      ‫جوابــه ومــن ثــم اجلــواب وأعطــي اخلصمــان جلســة يف يــوم االحــد‬\n      ‫‪1433/7/20‬ه ـ الســاعة العاشــرة والنصــف صباحــا ففــي يــوم األحــد‬\n      ‫املوافــق‪ 1433/07/20‬ه ـ افتتحــت اجللســة الســاعة وفيهــا حضــر‬\n      ‫املدعــي ‪.....‬وحضــر حلضــوره املدعــى عليــه ‪.....‬ثــم دفــع املدعــي علــى‬\n      ‫جــواب املدعــى عليــه بجــواب ‪.....‬صفحــات ولكــن ملخصــة ان صــك‬\n      ‫املدعــي عليــه هــو صــك دعــوى وليــس صــك اســتحكام وليــس لــه احلــق‬\n      ‫ان يعمــل يف أرضــي التــي املكهــا مبوجــب صــك شــراء متفــرع عــن حجــة‬\n      ‫اســتحكام وقــد هددنــي وفعــا نفــذ تهديــده باعتدائــه علــى اجلــزء‬\n      ‫اجلنوبــي مــن ارضــي ونقــل تربتهــا الــى االرض التــي يدعــي ملكيتهــا ثــم‬\n      ‫قــام بفتــح شــارع للتغييــر بذلــك املعالــم وصــك الدعــوى الــذي معــه‬\n      ‫مســاحته ســتة االف متــر فهــو أكثــر مــن القطــع املنظمــة املتعــارف عليهــا‬\n      ‫لالســتخدامات الشــخصية أمــا صكــي فلــه مــا يقــارب عشــرين ســنة‬\n      ‫حتــت يــدي وصــادر مــن كتابــة العــدل وان صكــي ســليم وإجــراءات‬\n      ‫افراغــه ســليمه وال يوجــد مــا يخــل بــه شــرعا او نظامــا انتهــى ملخصــا‬\n      ‫جــواب املدعــى عليــه ثــم طلبــت مــن املدعــي واملدعــي عليــه بــأن يحضــر‬\n      ‫كل واحــد منهمــا صكــه يف اجللســة القادمــة وقــال املدعي أنني مســافر‬\n\n\n‫‪135‬‬\n\f‫إلــى خــارج اململكــة واطلــب جلســة يف نهايــة شــوال وأعطــي اخلصمــان‬\n‫جلســة يف يــوم األحــد ‪1433/10/15‬ه ـ الســاعة التاســعة صباحــا ففــي‬\n‫يــوم األحــد املوافــق‪ 1433/10/15‬ه ـ افتتحــت اجللســة الســاعة ‪9.00‬‬\n‫وفيهــا حضــر املدعــي ‪ .....‬ولــم يحضــر املدعــى عليــه وســالته عــن صكــه‬\n‫فقــال انــه يف الوقــت احلاضــر مفقــود وســوف ابحــث عنــه مــع العلــم انــي‬\n‫ابــرزت صــورة لــه يف امللــف ثــم طلبــت منــه البحــث عنــه واعطــي جلســة‬\n‫وذلــك يف يــوم االثنــن ‪ 1433/11/8‬الســاعة ‪ 10.30‬ففــي يــوم االثنــن‬\n‫املوافــق ‪ 1433/11/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.00‬وفيهــا‬\n‫حضــر املدعــي وحضــر حلضــوره املدعــى عليــه ثــم ســألت املدعــي عــن‬\n‫صكــه فأبــرز لنــا صــورة لــه وهــذا نصــه احلمــد هلل وحــده والصــاة‬\n‫والســام علــى مــن ال نبــي بعــده وبعــد فلــدي أنــا ‪.....‬كاتــب عــدل ينبــع‬\n‫حالــه حضــر لــدي ‪.....‬بصفتــه وكيــا عــن البائــع ‪.....‬مبوجــب صــك‬\n‫التوكيــل الصــادر مــن كاتــب عــدل جــدة الثانيــة رقــم ‪ 46/2‬يف‬\n‫‪1402/10/11‬ه ـ وبعــد معرفــة ذاتــه وثبــوت تصرفاتــه قــرر طائعــا‬\n‫مختــارا وهــو بالصفــة املعتبــرة شــرعا بقولــة انــه مــن اجلــاري يف ملــك‬\n‫موكلــة وحتــت تصرفــه املزرعــة العثريــة الواقعــة يف العصيلــي بينبــع‬\n‫البحــر اململوكــة ملوكلــة مبوجــب الصــك الصــادر مــن محكمــة ينبــع‬\n‫برقــم ‪ 249‬يف ‪14397/5/19‬ه ـ قــد بعــت قســما مــن املزرعــة املذكــورة‬\n‫مــن جهــة املشــتريني وهمــا كل مــن ‪.....‬ســعودي باحلفيظــة رقــم ‪ 2497‬يف‬\n‫‪ 11/25‬واملدعــو ‪.....‬باحلفيظــة رقــم ‪ 1861‬يف ‪14378/8/19‬ه ـ وذلــك‬\n‫مببلــغ وقــدرة ثمانــون الــف ريــال اســتلمها عــدا ونقــدا وســلم املشــتريان‬\n‫االرض تســليم املثــل والبالــغ مســاحتها الضلــع الشــمالي واجلنوبــي كل‬\n‫واحــد منهمــا ‪200‬م والشــرقي والغربــي كل واحــد منهمــا ‪200‬م‬\n\n\n                                                                                   ‫‪136‬‬\n\f      ‫واحملــدودة مــن الشــمال مزرعــة ‪.....‬ومــن الغــرب واجلنــوب باقــي املزرعــة‬\n      ‫ومــن الشــرق طريــق ثــم مزرعــة ‪.....‬وبعــد تــاوة هــذا اإلقــرار علــى‬\n      ‫الطرفــن فهمــاه وأقــراه ووقعــا علــى ضبطــه أمامــي بحضــور شــهاده‬\n      ‫كل مــن ‪.....‬و ‪.....‬لــذا فقــد صدرتــه حتريــرا يف اليــوم ‪/27‬ربيــع اول ‪/‬‬\n      ‫‪1403‬ه ـ كاتــب العــدل علــي ‪.....‬ثــم مذيــل بأســفله صــورة احلمــد هلل‬\n      ‫وحــده وبعــد فقــد جــرى انتقــال كامــل محتــوى هــذا الصــك الــى ملــك‬\n      ‫املشــتري ‪.....‬وذلــك بتاريــخ ‪1413/5/2‬ه ـ وقــد حولــت األرض من زراعية‬\n      ‫إلــى ســكني وذلــك مبوجــب خطــاب بلديــة ينبــع رقــم ‪ 2208‬يف‬\n      ‫‪1422/7/8‬ه ـ حتــت توقيــع رئيــس كتابــة عــدل ينبــع ‪.....‬مــع العلــم ان‬\n      ‫رقــم الصــك هــو ‪ ....‬يف ‪1403/3/27‬ه ـ ومهمــش علــى خلــف الصــك مــا‬\n      ‫يلــي احلمــد هلل وحــده وبعــد بنــاء علــى خطــاب رئيــس بلديــة ينبــع البحــر‬\n      ‫رقــم ‪ .....‬يف ‪1428/6/26‬ه ـ القاضــي نصــه انــه برفــع املوقــع املذكــور‬\n      ‫بباطــن هــذا الصــك علــى الطبيعــة اتضــح ان هنــاك شــارع عــرض ‪30‬م‬\n      ‫مبســاحه ‪3025.94‬م داخــل الصــك وقــد جــرى تنســيقة بنفــس املوقــع‬\n      ‫وقــد أســتعد املالــك بالتنــازل لصالــح التنظيــم وأصبحــت ابعــاد املوقــع‬\n      ‫وحــدوده بعــد التنظيــم كمــا يلي أ‪ -‬أوال اجلزء الشــمالي الضلع الشــمالي‬\n      ‫بطــول ‪100‬م ويحــده شــارع ترابــي ثــم أثــار حــوش مهــدم والضلــع اجلنوبــي‬\n      ‫بطــول ‪101.50‬م ويحــده شــارع عــرض ‪30‬م والضلــع الشــرقي بطــول‬\n      ‫‪27,25‬م ويحــده طريــق ثــم مزرعــة ‪.....‬والضلــع الغربــي بطــول ‪72,60‬م‬\n      ‫ويحــده ارض بيضــاء مملوكــة لباقــي الصــك املفــرغ ومبســاحه تبلــغ‬\n      ‫‪4880,13‬م ب‪ -‬ثانيــا اجلــزء اجلنوبــي الضلــع الشــمالي بطــول ‪101,50‬م‬\n      ‫ويحــده شــارع عــرض ‪30‬م والضلــع اجلنوبــي بطــول ‪200‬م ويحــده ارض‬\n      ‫بيضــاء مملوكــة لباقــي الصــك والضلــع الشــرقي بطــول ‪141,80‬م‬\n\n\n‫‪137‬‬\n\f‫ويحــده طريــق ثــم مزرعــة ‪.....‬والضلــع الغربــي بطــول ‪96,45‬م ويحــده‬\n‫ارض بيضــاء مملوكــة لباقــي الصك املفرغ ومبســاحه تبلغ ‪11663,29‬م‬\n‫لــذا فقــد مت ضبطهــا لدينــا بعــدد جلــد االقاريــر جلــد ‪ 2/3/480‬صحيفــة‬\n‫‪ 25‬حتــد عــدد ‪ 2/3/12‬يف ‪1428/7/3‬ه ـ ومذيــل بأســفله كذلــك‬\n‫احلمــد هلل وحــده فقــد جــرى انتقــال اجلــزء الشــمالي بباطــن هــذا الصــك‬\n‫مللــك املشــتري ‪.....‬وذلــك بالشــراء الشــرعي حســبما اثبــت لدينــا بضبــط‬\n‫املبايعــات رقــم ‪ 5/4/497‬وصحيفــة رقــم ‪ 68‬وحتــرر لــه الصــك رقــم‬\n‫‪ 5/4/168‬يف ‪1429/1/11‬ه ـ رئيــس كتابــة عــدل بينبــع املكلــف ‪.....‬‬\n‫ثــم طلبــت مــن املدعــى عليــه إبــراز صــك او صــورة مصدقــة لــه وأســتعد‬\n‫بذلــك يف اجللســة القادمــة وذلــك يف يــوم الثالثــاء ‪1433/12/28‬ه ـ‬\n‫الســاعة التاســعة صباحــا ففــي يــوم الثالثــاء املوافــق‪ 1433/12/28‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9.00‬وفيهــا حضــر املدعــي وحضــر حلضــوره‬\n‫املدعــى عليــه ثــم ســألت املدعــى عليــه عــن صكــه فأبــرز لنــا اصــل‬\n‫الصــك الدعــوى رقــم ‪ 4/20‬يف ‪1428/3/7‬ه ـ الصــادر مــن محكمــة‬\n‫ينبــع مــن قبــل القاضــي بهــا ســابق ًا ‪.....‬وهــذا نصــه احلمــد هلل وحــده وبعــد‬\n‫لــدي انــا ‪.....‬القاضــي مبحكمــة ينبــع ففــي يــوم االثنــن املوافــق‬\n‫‪1428/3/7‬ه ـ افتتحــت اجللســة وفيهــا حضــر ‪.....‬وأدعــى علــى احلاضــر‬\n‫معــه ‪.....‬قائــا يف دعــواه انــه يف عــام ‪1420‬ه ـ اشــتريت مــن املدعــى عليــه‬\n‫االرض الواقعــة يف حــي العصيلــي الشــمالي مبحافظــة ينبــع والتــي‬\n‫يحدهــا مــن الشــمال ملــك ‪.....‬بطــول ‪200‬م ومــن اجلنــوب شــارع ثــم مزرعــة‬\n‫ملــك ‪.....‬بطــول ‪200‬م ومــن الشــرق شــارع ثــم مزرعــة ‪.....‬بطــول ‪60‬م ومــن‬\n‫الغــرب شــارع ثــم فضــاء بطــول ‪60‬م ومجمــوع مســاحتها ‪6000‬م بقيمــة‬\n‫إجماليــة ســبعون الــف ريــال وقــد قمــت بدفــع كامــل املبلــغ للمدعى عليه‬\n\n\n                                                                                         ‫‪138‬‬\n\f      ‫وطلبــت منــه أن يســلمني األوراق واملســتندات اخلاصــة بــاألرض حتــى‬\n      ‫أمتكــن مــن إجــراءات متلــك االرض عــن طريــق احملكمــة وأخــذ مياطلنــي‬\n      ‫يف ذلــك حتــى اخبرنــي اخيــر ًا انهــا مفقــودة لــذا أطلــب الزامــه بإعــادة‬\n      ‫املبلــغ الــذي ســلمته إيــاه وقــدرة ســبعون الــف ريــال هــذي دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه صــادق علــى دعــوى املدعــي جملــة وتفصيــا‬\n      ‫وقــال إننــي اســتلمت منــه كامــل املبلــغ وتعــذر علــي تســليمه االوراق‬\n      ‫واملســتندات الثبوتيــة اخلاصــة بــاألرض حيــث بحثــت عنهــا ولــم اجدهــا‬\n      ‫وال مانــع لــدي مــن إعــادة املبلــغ علــى أقســاط شــهرية حيــث ال اســتطيع‬\n      ‫دفــع املبلــغ كامــا يف الوقــت احلاضــر وبعــرض الصلــح بــن الطرفــن‬\n      ‫أتفــق ان يعيــد املدعــى عليــه للمدعــي عشــرين الــف ريــال علــى اقســاط‬\n      ‫شــهريه كل قســط الــف ريــال اعتبــارا مــن ‪1428/6/30‬ه ـ مقابــل عــدم‬\n      ‫تســليمه االوراق الثبوتيــة وتكــون قيمــة االرض حــن اذن خمســون الــف‬\n      ‫ريــال التــي ســبق أن اســتلمها املدعــى عليــه فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث اتفــق الطرفــان علــى مــا ذكــر بعاليــة فقــد‬\n      ‫ثبــت لــدي صحــة مــا اتفــق عليــه وحكمــت مبوجبــة وامضيتــه واجزتــه‬\n      ‫وبــاهلل التوفيــق حــرر يف ‪1428/3/7‬ه ـ القاضــي مبحكمــة ينبــع ‪.....‬ثــم‬\n      ‫ســالت املدعــى عليــه الديــك صــك غيــر هــذا فأجــاب بقولــة ال يوجــد لــدي‬\n      ‫غيــر هــذا الصــك ثــم ســالت املدعــى عليــه مــا نــوع اإلحيــاء يف تلــك االرض‬\n      ‫فأجــاب بقولــة عقــوم وبتــر ثــم ســألت املدعــى عليــه هــل عملــت فيهــا‬\n      ‫ا بعــد الشــراء فأجــاب بقولــة لــم اعمــل فيهــا شــئي ًا ثــم أجلــت اجللســة‬\n                                                                                      ‫عمـ ً‬\n      ‫لرصــد مضمــون حجــة االســتحكام االساســية رقــم ‪ 249‬يف‬\n      ‫‪1397/5/19‬ه ـ واعطــي اخلصمــان جلســة يف يــوم األحد ‪1434/2/17‬هـ‬\n      ‫الســاعة التاســعة صباحــا ففــي يــوم األحــد املوافــق‪ 1434/02/17‬ه ـ‬\n\n\n‫‪139‬‬\n\f‫افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي واملدعــى عليــه‬\n‫ثــم ســألت املدعــى عليــه كيــف آلــت اليــك االرض قــال عــن طريــق‬\n‫الشــراء مــن‪ .....‬قبــل خمســة عشــر ســنة ثــم اجلــت القضية لتأمــل وحددت‬\n‫موعــد اجللســة القادمــة يــوم الثالثــاء املوافق‪1434/4/2‬ه ـ الســاعة‬\n‫التاســعة ففــي يــوم األحــد املوافــق ‪1434/04/07‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 8.15‬وفيهــا حضــر املدعــي واملدعــى عليــه ويف الواقــع أن صــك‬\n‫املدعــي صــك إفــراغ متفــرع اساس ـ ًا مــن حجــة االســتحكام رقــم ‪249‬‬\n‫الصــادرة مــن فضيلــة الشــيخ ‪.....‬ومفادهــا أنــه تقــدم إليــه ‪ .....‬وانهــى أنــه‬\n‫مــن اجلــاري يف ملكــة وحتــت تصرفــه كامــل املزرعــة العثريــة الواقعــة‬\n‫يف شــرق العصيلــي ضواحــي ينبــع احملــدودة شــما ًال مســاقي املزرعــة‬\n‫وشــرق ًا الشــارع وبعــده مزرعــة ‪ .....‬وجنوب ـ ًا الفضــاء وغرب ـ ًا الطريــق ثــم‬\n‫مزرعــة ‪.....‬وكتــب يف كل مــن البلديــة واألوقــاف واملاليــة فكتبــت لــه‬\n‫البلديــة باملعارضــة وأتضــح لــه أن ذرعــة حجــة االســتحكام الضلــع‬\n‫الشــمالي ‪326‬م ومثلــة الضلــع اجلنوبــي والضلــع الشــرقي ‪400‬م ومثلــه‬\n‫الضلــع الغربــي وبعــد ســماع شــهادة الشــاهدين صــرف النظــر عــن‬\n‫معارضــة البلديــة إذ جــاء فيــه قولــة وصرفــت النظــر عــن معارضــة البلديــة‬\n‫وامــرت بإخــراج صــك وتســليمة للمنهــي ولــم يبعــث إلــى محكمــة‬\n‫االســتئناف ويف الواقــع أن النظــام ينــص علــى كل إثبــات إنهائــي خالــف‬\n‫االصــول اإلجرائيــة أو املوضوعيــة ال يصــح حملــة علــى الصحــة ولــزم‬\n‫رفعــة إلــى محكمــة االســتئناف وحجــة االســتحكام املذكــورة حتتــاج‬\n‫تتبــع وتقصــي وهــل تنطبــق علــى املوقــع ذرعــة وحــدود ًا وقــد عــارض‬\n‫املدعــى عليــه يف موقعهــا وقــد نــص النظــام وخاصــة يف املــادة احلاديــة‬\n‫واخلمســن بعد املئتني إذا رفعت املعارضة بعد خروج حجة االســتحكام‬\n\n\n                                                                                        ‫‪140‬‬\n\f      ‫ومصــدر احلجــة يف احملكمــة نفســها فتحــال إليــة ولــو أنتقــل إلى مكتب‬\n      ‫آخــر يف احملكمــة الواحــدة وإن لــم يكــن فخلفــة وحتســب لــه إحالــة‬\n      ‫وكذلــك قولــة إذا نشــأ اعتــراض علــى احلجــة قبــل قطعيتهــا ســمعت‬\n      ‫لــدى ناظــر احلجــة او خلفــه لــذى حكمــت بصــرف النظــر لعــدم‬\n      ‫االختصــاص ألن حجــة املدعــي هــو صكــه وصكــه متفــرع عــن حجــة‬\n      ‫اســتحكام مخالفــة لألصــول اإلجرائيــة ولســت خلف ـ ًا ملصــدر حجــة‬\n      ‫االســتحكام وبعــرض ذلــك علــى املدعــي قــال إننــي غيــر قانــع وكذلــك‬\n      ‫قــال املدعــى عليــه إننــي غيــر قانــع وجــرى تســليم كل واحــد صــورة مــن‬\n      ‫احلكــم لالعتــراض عليــه ومــدة االعتــراض شــهر منــذ تســلمه وبعــد‬\n      ‫الشــهر يســقط حقــة يف االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/07‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪.....‬القاضــي يف احملكمــة العامــة بينبــع وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بينبــع برقــم‬\n      ‫‪ 32538467‬وتاريــخ ‪ 1432/11/18‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 321436968‬وتاريــخ ‪ 1432/11/13‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافــق‪ 1434/07/01‬ه ـ افتتحت اجللســة الســاعة الثامنــة واربع صباحا‬\n      ‫ثــم أعيــدت لنــا املعاملــة مــن محكــة االســتئناف مبكة مبوجــب خطابها‬\n      ‫رقــم ‪ 341260729‬يف ‪1434/6/19‬ه ـ املرفــق بهــا قــرار املالحظــة رقــم‬\n      ‫‪34237060‬يف ‪1434/6/11‬ه ـ والــذي جــاء فيــه قولــه وبدراســة احلكــم‬\n      ‫وصــورة ضبطــه تقــرر إعادتهــا لناظــر القضيــة حيــث لــم جنــد فضيلتــه‬\n      ‫عمــل أي إجــراء علــى ضــور قــرار املالحظــة املرفــق رقــم ‪ 33148022‬يف‬\n      ‫‪1433/3/22‬ه ـ فيتعــن إكمــال الــازم حســبما صــدر لفضيلتــه مــن‬\n\n\n‫‪141‬‬\n\f‫توجيــه وبــاهلل التوفيــق قاضــي اســتئناف ‪.....‬قاضــي اســتئناف ‪.....‬رئيــس‬\n‫الدائــرة ‪ .....‬عليــه نعيــد كامــل املعاملــة وبرفقهــا كامــل مــا أجريتــه‬\n‫ســابقا علــى ضــوء وقــرار املالحظــة املذكــورة ولكــن الصــك أساســا‬\n‫أرفــق مبعاملــة أخــرى عــن طريــق الســهو وعليــه فقــد جــرى إكمــال‬\n‫الــازم حيــال املالحظــة املذكــورة وإعادتهــا ألصحــاب الفضيلــة وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                        ‫‪1434/07/01‬هـ ‪.‬‬\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34279180‬وتاريــخ‬\n                                                 ‫‪1434/7/25‬هـ‬\n\n\n\n\n                                                                                 ‫‪142‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":130,"source_page_end":142,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a63187bb75987b075165d7a424caeffdf3acf975b052cedf351138b61268684a","normalized_text_hash":"c9723dfebb2973e12d7f66e9f62f43cea24bc83806b0f0caa62f4a93681faf7c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p130-33122571"},{"id":"26e391e2-e90d-54d6-89af-fd1dd0573e30","document_type":"judgment","category":"judicial","subcategory":"general","title":"جن-ض عن م د ة س اختصاص -دع وى ض د جه ة حكومي ة -تعوي","document_number":"34197496","case_number":"33245634","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/24","year":"1434","subject":"جن-ض عن م د ة س اختصاص -دع وى ض د جه ة حكومي ة -تعوي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/24 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34197496 :‬‬\n                   ‫َر ْق ُم الدعوى‪33245634 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34241081‬تاريخه ‪1434/6/14 :‬هـ‬\n\n\n‫ـجن‪-‬‬‫ـض َعــن ُمـ َّـد ِة سـ ٍ‬\n                           ‫اختصــاص ‪َ -‬دع ـ َوى ِضـ َّـد ِجه ـ ٍة ُحكومي ـةٍ‪ -‬تعويـ ٌ‬\n‫دون طلـ ِـب‬\n         ‫ـاص َ‬     ‫ـاص مـ َـن ال ِّنظــا ِم العــا ِّم‪ -‬بحـ ُـث االخ ِتصـ ِ‬\n                                                                        ‫مســأل ُة االخ ِتصـ ِ‬\n ‫ـض ِضـ َّـد أجهــز ِة الدول ـ ِة مـ ِـن اخ ِتصـ ِ‬\n‫ـاص‬                                                      ‫اخلصــو ِم‪ -‬دعــا َوى ال َّتعويـ ِ‬\n ‫ـاص‪.‬‬ ‫الدع ـ َوى لعــد ِم االخ ِتصـ ِ‬‫احملكم ِــة اإلداري ـةِ‪َ -‬صـ ْـر ُف ال َّنظ ـ ِر عـ ِـن َّ‬\n\n\n\n\n                              ‫املظالم‪.‬‬\n                               ‫ِ‬          ‫‪ -1‬املا َّد ُة َر ْق ُم ‪/13‬ج مِ ن نِظا ِم دِيوانِ‬\n           ‫ور ْق ُم (‪ )217‬مِ ن نِظا ِم اإلجراءاتِ اجلزائيةِ‪.‬‬\n                                                          ‫‪ -2‬املا َّد ُة َر ْق ُم (‪َ )216‬‬\n\n\n\n\n‫طالبــا بــر ِّد‬\n              ‫ـام ُم ً‬    ‫املدعِ ــي ِضـ َّـد ممثـ ِـل هيئ ـ ِة التحقيـ ِـق واالدعــا ِء العـ ِّ‬\n                                                                                               ‫ا َّد َعــى َّ‬\n‫ـنتي مِ ــن قِ بـ ِـل‬ ‫ـجن مـ َّـد َة سـ ْ ِ‬\n                                          ‫ـث ُسـ َ‬    ‫وتعويضــه َعــن ُمــد ِة ســجنِه؛ حيـ ُ‬\n                                                                                        ‫ِ‬         ‫اعتبــا ِره‬\n‫ِف‬  ‫كان يس ـع ُ‬     ‫َ‬        ‫ن‬‫ـام بــدونِ وج ـ ِه حـ ٍّـق ح ـ َ‬  ‫هيئ ـ ِة التحقيـ ِـق واالدعــا ِء العـ ِّ‬\n‫ـض‬     ‫املد َعــى علي ـ ِه قُ بـ َ‬‫ـأن َّ‬‫ـاب ممثــلُ الهيئ ـ ِة بـ َّ‬‫ـخصا حسـ َـب دعـ َـو ُاه‪ ..‬أجـ َ‬ ‫شـ ً‬\n‫ـك ٍر‪،‬‬    ‫كان بحال ـ ِة ُسـ ْ‬   ‫َ‬          ‫ـخص‪ ،‬وقَ ــد‬  ‫ـرق شـ ٍ‬  ‫علي ـ ِه ع َلــى خلفي ـ ِة قضي ـ ِة حـ ِ‬\n‫ـيش املخـ ِّـد ِر فتـ َّـم‬  ‫ـكر وحِ يــاز ِة احلشـ ِ‬    ‫وبقياد ِتــه الســيار ِة حتـ َـت تأثيـ ِـر املسـ ِ‬\n‫ـط اجلنائـ ِّـي‪ ،‬و ُأحيلـ ْـت دعـ َـوى‬            ‫ن مــن قِ بــل رجــالِ الضبـ ِ‬‫فص ُلهــا إلــى قضيتـ ِ‬\n‫ـدر في َهــا ُحكـ ٌـم‪ ،‬و ُأحيلـ ْـت‬              ‫ـك ِر إلــى احملكم ـ ِة اجلزائي ـةِ‪ ،‬وصـ َ‬           ‫السـ ْ‬\n                                                                                                          ‫ُّ‬\n‫ـص‬   ‫العام ـ ِة وال تــزال منظــور ًة‪ ،‬واملختـ ُّ‬          ‫َّ‬       ‫دعـ َـوى القتـ ِـل إلــى احملكم ـ ِة‬\n\n                                                                                                                ‫‪160‬‬\n\f      ‫ـاق َســراحِ ِه احملكم ـ ُة بعـ َـد إحال ِتهــا إلي َهــا حسـ َـب املــا َّد ِة ‪ 123‬مــن‬                             ‫بإطـ ِ‬\n      ‫ـاص‬   ‫أن االخ ِتصـ َ‬             ‫ومبــا َّ‬  ‫أجــاب‪َ ..‬‬      ‫ـراءات اجلزائي ـةِ؛ هكـ َـذا َ‬              ‫ِ‬       ‫ـام اإلجـ‬     ‫ِنظـ ِ‬\n      ‫ـائل اجلوهريـ ِة ا َّلتــي ال ُبـ َّـد مـ َـن ال َّنظـ ِـر في َهــا ولـ ْـو لـ ْـم يطلـ ْـب‬          ‫الوالئـ َّـي مـ َـن املسـ ِ‬\n        ‫ـام ِديــوانِ‬ ‫إن املــا َّد َة َر ْقـ َـم (‪/13‬ج) مــن ِنظـ ِ‬              ‫ـث َّ‬   ‫ن‪ ،‬وحيـ ُ‬     ‫ذلـ َـك أحـ ُـد املتداع ـ َ‬\n      ‫ـوم امللكـ ِّـي َر ْقـ ِـم م‪ 78/‬يف ‪1428/09/19‬ه ـ قَ ــد‬                                    ‫الصــاد ِر باملرسـ ِ‬  ‫املظالـ ِـم َّ‬\n      ‫الشــأنِ َعن‬     ‫وو َّ‬       ‫يقدمهــا َذ ُ‬\n                                            ‫ُ‬          ‫ـض ا َّلتــي‬‫ـاوى ال َّتعويـ ِ‬     ‫جعلـ ْـت للديــوانِ ال َّنظـ َـر يف دعـ َ‬\n      ‫جميعهــا‬‫َ‬          ‫ـط اجلنائـ ِّـي‬      ‫ـات الضبـ ِ‬      ‫إن ِجهـ ِ‬    ‫ـث َّ‬   ‫ـرارات وأعمــالِ اإلدارةِ‪ ،‬وحيـ ُ‬       ‫ِ‬            ‫قـ‬\n          ‫ِ‬\n      ‫ـراءات‬        ‫ـإن إجـ‬  ‫ـرارات إداريـ ًة‪ ،‬وكذلـ َـك فـ َّ‬          ‫ٍ‬             ‫ـات إداريـ ٌة‪ ،‬و ُتعــد قرارا ُتهــا قـ‬      ‫ِجهـ ٌ‬\n      ‫املختصـ ِة بالفصـ ِـل‬     ‫َّ‬             ‫ـط اجلنائـ ِّـي ال تخضـ ُـع لرقابـ ِة احملكمـ ِة اجلزائيـ ِة‬                   ‫الضبـ ِ‬\n      ‫إن احملكم ـ َة اإلداري ـ َة هـ َـي صاحب ـ ُة‬                             ‫ـث َّ‬    ‫الدعـَـوى اجلزائي ـةِ‪ ،‬وحيـ ُ‬            ‫يف َّ‬\n      ‫ـض ِضـ َّـد‬    ‫ـاوى ال َّتعويـ ِ‬         ‫ـاوى اإلداري ـةِ‪ ،‬و َدعـ َ‬            ‫الدعـ َ‬ ‫العام ـ ِة يف َنظـ ِـر َّ‬\n                                                                                                                   ‫َّ‬         ‫الوالي ـ ِة‬\n      ‫املدعِ ــي‬  ‫ـرف ال َّنظـ ِـر َعــن َدعـ َـوى َّ‬            ‫أجهــز ِة الدول ـ ِة اإلداري ـةِ‪ ..‬احلكـ ُـم بصـ ِ‬\n      ‫املد َعــى‬‫ـرض َّ‬    ‫املدعِ ــي با ُحلكـ ِـم‪ ،‬واعتـ َ‬                ‫ـاص الوالئـ ِّـي‪ ..‬قنـ َـع َّ‬         ‫ـدم االخ ِتصـ ِ‬      ‫لعـ ِ‬\n      ‫عليـ ِه بالئحـةٍ‪َ ،‬صـ َـد َر ا ُحلكـ ُـم مـ َـن الدائــر ِة اجلزائيـ ِة السادسـ ِة مبحكمـ ِة‬\n                                                                      ‫ك ـ َة املكرم ـةِ‪.‬‬          ‫ـتئناف مبنطق ـ ِة َم َّ‬‫ِ‬            ‫االسـ‬\n\n\n\n\n      ‫ـدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬      ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n      ‫ـاء علــى املعاملــة احملالــة إلينــا مــن قِ بــل فضيلــة‬\n                                                               ‫مبكــة املكرمــة‪ ،‬وبنـ ً‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33245634‬وتاريــخ‬\n      ‫‪1433/04/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33553377‬وتاريــخ‬\n      ‫‪1433/03/23‬هـ‪ ..‬إنه يف يوم األربعاء املوافق ‪1434/04/24‬هـ افتتحت‬\n      ‫اجللســة‪ ،‬وفيهــا حضــر املدعــي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n\n‫‪161‬‬\n\f‫املدنــي رقــم ‪ ...‬كمــا حضــر حلضــوره املدعــى عليــه ممثــل هيئــة التحقيــق‬\n‫واالدعــاء العــام ‪ ...‬الكليــة ســعودي بالســجل املدني رقــم ‪ ...‬وأبرز املدعي‬\n‫دعــواه احملــررة وهــذا نصهــا‪« :‬إننــي قــد ســجنت ملــدة ســنتني بــدون وجــه‬\n    ‫حــق مــن قِ بــل دائــرة النفــس يف إدارة االدعــاء العام عند إســعايف شـ ً‬\n‫ـخصا؛‬\n‫لــذا أطلــب رد اعتبــاري وتعويضــي عــن املــدة التــي ُســجنت فيهــا مــن‬\n‫مكتوبــا‪ ،‬هــذا‬\n           ‫ً‬         ‫قبلهــم»‪ ..‬وبعرضهــا علــى ممثــل الهيئــة احلاضــر أبــرز ر ًّدا‬\n‫نصــه‪« :‬إشــار ًة خلطــاب ســعادة مديــر مكتبكــم رقــم (‪)34/856099‬‬\n‫بتاريــخ ‪1434/4/7‬ه ـ املرفــق بــه صــورة مــن صحيفــة الدعــوى املقدمــة‬\n‫مــن املدعــي‪ .../‬ضــد هيئــة التحقيــق واالدعــاء العــام مبكــة املكرمــة‪،‬‬\n‫مفادهــا أن دائــرة النفــس بالفــرع قــد ســجنته ملــدة ســنتني بــدون وجــه حــق‬\n‫ـخصا‪ ،‬ويرغــب يف رد اعتبــاره وتعويضــه عــن املــدة التــي‬      ‫عنــد إســعافه شـ ً‬\n‫أمضاهــا بالســجن‪ ..‬وعليــه‪ ،‬فأقــدم لفضيلتكــم الــرد علــى الدعــوى‬\n‫املشــار إليهــا بأعــاه بــأن املذكــور قبــض عليــه بتاريــخ ‪1429/4/7‬ه ـ‬\n‫(مرفــق صــورة مــن أمــر التوقيــف وصــورة مــن أمــر التمديــد‪ ،‬التوقيــف‬\n‫للمــرة األولــى) مــن قِ بــل رجــال الضبــط اجلنائــي علــى خلفيــة قضيــة حــرق‬\n‫ـكر وبقيادتــه الســيارة حتــت‬         ‫شــخص‪ ،‬وقــد كان املدعــي بحالــة سـ ْ‬\n‫تأثيــره وحيازتــه احلشــيش املخــدر بقصــد االســتعمال‪ ،‬فتــم فصــل هــذه‬\n‫القضيــة مــن قِ بــل جهــة الضبــط اجلنائــي قبــل إحالتهــا جلهــة التحقيــق‬\n‫طرفنــا إلــى قضيتــن‪( :‬ا) األولــى‪ :‬قضيــة الســكر وقيادتــه للســيارة‬\n‫حتــت تأثيــره وحيازتــه للحشــيش املخــدر بقصــد االســتعمال‪ ،‬ومتــت‬\n‫إحالتهــا مــن قِ بــل االدعــاء العــام إلــى احملكمــة اجلزائيــة برقــم (‪)28567‬‬\n‫يف ‪1429/8/19‬هــ؛ أي بعــد أربعــة أشــهر مــن تاريــخ القبــض عليــه‪،‬‬\n‫وصــدر بتاريــخ ‪1429/11/3‬ه ـ القــرار الشــرعي رقــم(‪( )6/442‬املرفــق‬\n\n\n                                                                                         ‫‪162‬‬\n\f      ‫لكــم صــورة منــه)‪ ،‬واملتضمــن ثبــوت شــربه للمســكر وقيادتــه للســيارة‬\n      ‫حتــت تأثيــره وحيــازة احلشــيش املخــدر بقصــد االســتعمال‪ ،‬واحلكــم‬\n      ‫بحــد الســكر وســجنه أربعــة أشــهر مــن تاريــخ التوقيــف‪ ،‬ومنعــه مــن‬\n      ‫الســفر ملــدة ســنتني‪ ،‬واقتنــع املتهــم باحلكــم‪( .‬ب) الثانيــة‪ :‬قضيــة القتــل‬\n      ‫املنظــورة لديكــم متــت إحالتهــا مــن قِ بــل االدعــاء العــام إلــى احملكمــة‬\n      ‫العامــة برقــم ‪ ..........‬يف ‪1429/11/25‬ه؛ أي بعــد ســبعة أشــهر مــن تاريــخ‬\n      ‫القبــض عليــه‪ ،‬واســتنا ًدا للمــادة (‪ )123‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫فــإن هيئــة التحقيــق املتمثلــة يف دائــرة النفــس ال تســتطيع إطــاق ســراحه‬\n      ‫مــن هــذه القضيــة؛ ألن لــه قضيــة أخــرى املذكــورة يف الفقــرة ا متــت‬\n      ‫إحالتهــا للمحكمــة اجلزائيــة؛ فهــي اجلهــة املختصــة بإطــاق ســراحه مــن‬\n      ‫ـاء علــى مــا تقــدم فــإن مــا ادعــى بــه املذكــور مــن أن هيئــة‬   ‫عدمــه‪ .‬فبنـ ً‬\n      ‫التحقيــق أوقفتــه ملــدة ســنتني غيــر صحيــح‪ ،‬وال دليــل عليــه‪ ،‬وال عالقــة‬\n      ‫للهيئــة بهــذه املــدة‪ ،‬وأن إجــراءات الهيئــة مــن حيــث التحقيــق واإليقــاف‬\n      ‫واالتهــام يف كلتــا القضيتــن كانــت نظاميــة‪ ،‬وأن إحالــة أوراقــه يف‬\n      ‫وفقــا لنظامــي اإلجــراءات‬  ‫أيضــا‪ ،‬وذلــك ً‬     ‫أثنــاء مــدة توقيفــه نظاميــة ً‬\n      ‫اجلزائيــة‪ ،‬وهيئــة التحقيــق واالدعــاء العــام بدليــل صــدور حكــم عليــه‬\n      ‫يف القضيــة األولــى املشــار إليــه بأعــاه‪ ،‬وكــون القضــاء قــد بــرأه مــن‬\n      ‫القضيــة الثانيــة؛ فهــذا ال يقــدح يف صحــة إجــراءات التحقيــق التــي متــت‬\n      ‫ـاء علــى مــا تقــدم من الدعوى واإلجابــة‪ ،‬وحيث إن االختصاص‬               ‫معــه‪ ..‬وبنـ ً‬\n      ‫الوالئــي مــن املســائل اجلوهريــة التــي ال بــد مــن النظــر فيهــا ولــو لــم يطلــب‬\n      ‫ذلــك أحــد املتداعــن‪ ،‬وحيــث إن املــادة رقــم (‪/13‬ج) مــن نظــام ديــوان‬\n      ‫املظالــم الصــادر باملرســوم امللكــي رقــم م‪ 78/‬يف ‪1428/09/19‬ه ـ قــد‬\n      ‫ـاوى التعويــض التــي يقدمهــا ذوو الشــأن عن‬       ‫جعلــت للديــوان النظــر يف دعـ َ‬\n\n‫‪163‬‬\n\f‫قــرارات وأعمــال اإلدارة‪ ،‬وحيــث إن جهــات الضبــط اجلنائــي جميعهــا‬\n‫جهــات إداريــة و ُتعــد قراراتهــا قــرارات إداريــة‪ ،‬وكذلــك فــإن إجــراءات‬\n‫الضبــط اجلنائــي ال تخضــع لرقابــة احملكمــة اجلزائيــة املختصــة بالفصــل‬\n‫يف الدعــوى اجلزائيــة‪ ،‬وحيــث إن مبــدأ اختصــاص الديــوان بالنظــر يف‬\n‫ـابقا‪ ،‬وصدرت‬   ‫هذه الدعوى ونظائرها قد اســتقر عليه عمل الديوان سـ ً‬\n‫تأسيســا علــى ذلــك عــدة قــرارات؛ منهــا القــرار رقــم ‪/2‬د‪/‬ف‪ 4/‬لعــام‬  ‫ً‬\n‫‪1417‬ه ـ يف القضيــة رقــم ‪/1/750‬ق لعــام ‪1421‬ه ـ املؤيــد باحلكــم رقــم‬\n‫‪/318‬ت‪ 1/‬لعــام ‪1427‬ه ـ وغيرهــا‪ ،‬وحيــث إن دعــوى طلــب التعويــض‬\n‫دعــوى مســتقلة مــن حيــث اإلجــراءات واملوضــوع عــن الدعــوى اجلنائيــة‪،‬‬\n‫خاصــا بهــا‪ ،‬ولعمــوم املادتــن رقــم‬\n                                   ‫نظاميــا ًّ‬\n                                          ‫ًّ‬     ‫وألن لــكل دعــوى كيا ًنــا‬\n‫(‪ )216‬ورقــم (‪ )217‬مــن نظــام اإلجــراءات اجلزائيــة الصــادر باملرســوم‬\n‫وتأسيســا علــى مــا ســبق‬\n                     ‫ً‬      ‫امللكــي رقــم م‪ 39/‬وتاريــخ ‪1422/07/28‬هــ‪،‬‬\n‫وحيــث إن احملكمــة اإلداريــة هــي صاحبــة الواليــة العامــة يف نظــر‬\n‫ـاوى التعويــض ضــد أجهــزة الدولــة اإلداريــة وليس‬   ‫ـاوى اإلداريــة ودعـ َ‬\n                                                                          ‫الدعـ َ‬\n‫للقضــاء العــام أن يقــرر مســؤولية الدولــة عــن أي عمــل إال مبوجــب نــص‬\n‫يخولــه االختصــاص بذلــك‪ ،‬وألن القاعــدة النظاميــة املســتقرة‬       ‫صريــح ّ‬\n‫واملتفــق عليهــا أنــه (ال اجتهــاد مــع النــص)؛ لذلــك كلــه فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي لعــدم االختصــاص الوالئــي بنظرهــا كونهــا‬\n‫مــن اختصــاص احملكمــة اإلداريــة‪ ..‬وبعــرض ذلــك علــى الطرفــن‪ ،‬قنــع‬\n‫بــه املدعــي وقــرر املدعــى عليــه ممثــل هيئــة التحقيــق واالدعــاء العــام‬\n‫اعتراضــه علــى احلكــم بالئحــة‪ ،‬فجــرى تســليمه نســخة مــن القــرار‬\n‫و ُأفهــم بتعليمــات االعتــراض‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى‬\n                    ‫نبينــا محمــد وآلــه وصحبــه‪ُ .‬حــرر يف ‪1434/04/24‬هــ‪.‬‬\n\n\n                                                                                    ‫‪164‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ..‬وبعــد‪،‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n      ‫مبكــة املكرمــة‪ ،‬جــرى منــا االطِّ ــاع علــى املعاملــة الــواردة إلــى هــذه‬\n      ‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة‬\n      ‫رقــم ‪ ................‬بتاريــخ (‪1434/5/25‬هــ) املرفــق بهــا القــرار رقــم‬\n      ‫(‪ )34197496‬بتاريــخ (‪1434/4/24‬هــ) الصــادر عــن فضيلــة الشــيخ‪/‬‬\n      ‫‪ ...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‪ ،‬املتضمــن دعــوى‪/‬‬\n      ‫‪ ...‬ســعودي اجلنســية‪ ،‬ضــد هيئــة التحقيــق واالدعــاء العــام يف قضيــة‬\n      ‫منظــورة احملكــوم فيــه مبــا دون باطنــه‪ ..‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‪ ،‬واهلل‬\n         ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪165‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":160,"source_page_end":165,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8544ef38d3c878191cb33eea5ccfd027f49e6a8ebb3da83b732709d12feefac","normalized_text_hash":"5db4a3b1aff91b924dc79ae76e0045a7917bfb65f1989660e3fb1ab22f7c5707","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p160-34197496"},{"id":"b8bd81d4-4db8-59d2-a8be-97427696cde6","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -ع ق د ع مال ة -خالف ات ع مالي ة -مس","document_number":"34181516","case_number":"33332216","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/7","year":"1434","subject":"اختصاص -ع ق د ع مال ة -خالف ات ع مالي ة -مس","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/7 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34181516 :‬‬\n                   ‫َر ْق ُم الدعوى‪33332216 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34221355‬تاريخه ‪1434/5/25 :‬هـ‬\n\n\n‫ـتحقات متأخــر ٌة‬\n           ‫ٌ‬                               ‫اختصــاص ‪َ -‬ع ْقـ ُـد عِ مال ـةٍ‪ِ -‬خالفـ ٌ‬\n                      ‫ـات ُع َّمالي ـ ٌة‪ُ -‬مسـ‬\n           ‫ـاص والئـ ٍّـي‪.‬‬\n                        ‫العمــلِ ‪ -‬عــد ُم اختصـ ٍ‬  ‫ـات مِ ــن صاحـ ِـب َ‬    ‫و َتعويضـ ٌ‬\n\n\n\n\n                                   ‫الفِ ْقر ُة األو َلى مِ َن املا َّد ِة اخلامِ س ِة مِ ن نِظا ِم َ‬\n                              ‫العملِ ‪.‬‬\n\n\n\n\n ‫وبعد أنْ‬\n     ‫املد َعى علي َها‪َ ،‬‬           ‫كان موظَّ ًفــا َ‬\n                    ‫لدى الشــرك ِة َّ‬            ‫َ‬   ‫املدعِ ــي بأ َّنــه‬\n                                                                     ‫ا َّد َعــى َّ‬\n‫تبقــى‬                ‫أجـ َـرى عمليـ ًة جراحيـ ًة أن َهـ ْـت خِ دْ ما ِتــه وهـ َـو يف فتــر ِة العـ ِ‬\n        ‫ـاج‪ ،‬وقَ ــد َّ‬\n‫ـزام‬\n  ‫فقــد طالـ َـب بإلـ ِ‬    ‫ـواه؛ لـ َـذا َ‬\n                                       ‫مفصل ـ ٌة يف َد ْعـ ُ‬‫ـتحقات َمالي ـ ٌة لدي َهــا َّ‬‫ٌ‬         ‫ل ـ ُه ُمسـ‬\n‫ـارج‬\n   ‫الدعـ َـوى خـ َ‬  ‫ـال‪ ..‬العقـ ُـد محــلُّ َّ‬   ‫املد َعــى علي َهــا بدف ِعهــا لـ ُه حـ ً‬ ‫الشــرك ِة َّ‬\n‫ـص‬   ‫العمـ ِـل فتختـ ُّ‬‫ـام َ‬‫اض ًعــا ل ِنظـ ِ‬\n                                            ‫لكو ِنــه َخ ِ‬\n                                                         ‫ْ‬         ‫العام ـ ِة‬\n                                                                        ‫َّ‬    ‫ـاص احملاكـ ِـم‬    ‫اخ ِتصـ ِ‬\n‫قضـ ِـت احملكمـ ُة‬                  ‫العماليـ ِة مبكتـ ِـب َ‬\n                        ‫العمـ ِـل‪َ ..‬‬                                ‫ـات ُ‬ ‫بـ ِه َهيئـ ُة َتســوي ِة اخلِالفـ ِ‬\n‫ـاص الوالئـ ِّـي‪ ،‬قنـ َـع‬ ‫ـدم االختصـ ِ‬       ‫املدعِ ــي لعـ ِ‬‫ـرف ال َّنظـ ِـر َعــن ُمطالب ـ ِة َّ‬ ‫بصـ ِ‬ ‫َ‬\n‫رت‬  ‫املدعِ ــي‪ ..‬وقــدْ قـ َّـر ْ‬\n                              ‫ض علي ـ ِه َّ‬     ‫ـار َ‬\n                                                   ‫املد َعــى علي َهــا با ُحلكـ ِـم وعـ َ‬     ‫وكيــلُ َّ‬\n                                             ‫ـتئناف املصادق ـ َة ع َلــى احل ْ‬\n                                      ‫ُكـ ِـم‪.‬‬                                    ‫محكم ـ ُة االسـ ِ‬\n\n\n\n\n                                                                                                                  ‫‪166‬‬\n\f      ‫ـدي أنــا املــازم القضائــي ‪ ...‬واملكلــف‬       ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n      ‫بنظــر هــذه الدعــوى مــن قبلــي باملكتــب القضائــي ‪ ...‬باحملكمــة‬\n      ‫ـاء علــى املعاملــة احملالــة إلينــا مــن قِ بــل فضيلــة رئيــس‬\n                                                                     ‫العامــة بالدمــام بنـ ً‬\n      ‫احملكمــة العامــة بالدمــام برقــم ‪ 33332216‬وتاريــخ ‪1433/05/12‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33902546‬وتاريــخ ‪ 1433/05/12‬ه ـ حضــر‬\n      ‫‪ ...‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪ .....‬وســارية املفعــول حتــى‬\n      ‫‪1434/07/01‬ه ـ وحضــر حلضــوره ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬الوكيــل الشــرعي‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬بصفتــه وكيـ ًـا عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة عــن كتابــة عــدل الدمــام‬\n      ‫الثانيــة برقــم ‪ 5106‬يف ‪1432/01/28‬ه ـ واملجلــد رقــم ‪ 9084‬مبوجــب‬\n      ‫الوكالــة الصــادرة عــن كتابــة عــدل الدمــام الثانيــة برقــم ‪60967‬‬\n      ‫يف ‪1432/12/25‬ه ـ واملجلــد رقــم ‪ 9758‬وادعــى املدعــي قائـ ًـا‪ :‬لقــد‬\n      ‫موظفــا لــدى شــركة ‪ ..‬منــذ تاريــخ ‪1415/07/07‬ه ـ املوافــق‬          ‫ً‬       ‫كنــت‬\n      ‫ـتمررت معهــم‬\n                 ‫ُ‬     ‫‪1994/12/10‬م بوظيفــة مهنــدس ميكانيــكا واسـ‬\n      ‫حتــى تاريــخ ‪1419/9/5‬ه ـ املوافــق ‪2000/08/23‬م وقــد أجريــت‬\n      ‫عمليــة جراحيــة نتيجــة تعرضــي لتعــب شــديد مبستشــفى ‪ ...‬بتحويــل‬\n      ‫مــن الشــركة يف تاريــخ ‪1421/02/04‬ه ـ ‪2000/05/09‬م وكنــت‬\n      ‫وقتهــا حتــت كفالــة الشــركة‪ ،‬وأنهيــت خدماتــي وأنــا يف فتــرة العــاج‬\n      ‫وحيــث تبقــى يف ذمــة الشــركة مســتحقات ماليــة لــي وهــي علــى النحــو‬\n      ‫ألفــا وتســعمائة وعشــرة ريــاالت مقابــل‬   ‫التالــي‪ :‬مبلــغ وقــدره اثنــا عشــر ً‬\n\n‫‪167‬‬\n\f‫نهايــة اخلدمــة مــن تاريــخ ‪1415/07/07‬ه ـ املوافــق ‪1994/12/10‬م حتى‬\n‫تاريــخ ‪1421/10/07‬ه ـ املوافــق ‪2001/01/03‬م؛ ومبلــغ وقــدره أربعــة‬\n‫ـال مقابــل إجــازة غيــر مدفوعــة؛‬ ‫آالف وخمســمائة وواحــد وتســعون ريـ ً‬\n          ‫ألفــا ومائــة وثالثــة عشــر ريـ ً‬\n‫ـال مقابــل‬                                ‫ومبلــغ وقــدره اثنــان وعشــرون ً‬\n‫رواتــب متأخــرة مــن تاريــخ ‪1421/03/28‬ه ـ املوافــق ‪2000/07/01‬م‬\n‫حتــى ‪1421/10/07‬ه ـ املوافــق ‪2001/01/03‬م؛ ومبلــغ وقــدره ألــف‬\n‫ريــال مقابــل مــا قمــت بدفعــه مبستشــفى ‪ ...‬لشــراء مضــادات حيويــة‬\n‫وأدويــة؛ ومبلــغ وقــدره أربعــة آالف ريــال مقابــل غيــارات ومطهــرات‬\n‫وأدويــة وكشــوفات باملستشــفى‪ ،‬ليصبــح مجمــوع مــا أطالــب إلــزام‬\n                                     ‫الشــركة املدعــى عليهــا بدفعــه لــي حـ ً‬\n‫ـال مبل ًغــا وقــدره خمســة وأربعــون‬\n‫ـال؛ هــذه دعــواي‪ .‬وبعــرض ذلــك علــى‬     ‫ألفــا وســتمائة وأربعــة عشــر ريـ ً‬\n                                                                              ‫ً‬\n‫املدعــى عليــه وكالـ ًة أجــاب قائـ ًـا‪ :‬أطلــب إمهالــي لإلجابــة علــى دعــوى‬\n‫املدعــي؛ هكــذا أجــاب‪ ..‬ولــذا جــرى رفــع اجللســة‪ ،‬ويف جلســة أخــرى‬\n‫افتتحــت اجللســة أنــا ‪ ...‬القاضــي باحملكمــة العامــة بالدمــام بحضــور‬\n‫آنفــا‪ ،‬ونظـ ًـرا النتقــال املــازم القضائــي‬\n                                             ‫الطرفــن املرصــودة بياناتهمــا ً‬\n‫عــن املكتــب فقــد قــررت االســتمرار يف نظــر القضيــة‪ ،‬وبتــاوة مــا‬\n‫ســبق علــى املدعــي صــادق عليــه وبســؤال املدعــى عليــه بالوكالــة عــن‬\n‫إجابتــه أبــرز لنــا ورقتــن حتمــان مطبوعــات مؤسســة ‪ ...‬ومؤرخــة يف‬\n‫‪1433/08/03‬ه ـ وموقعــة مــن قِ بلــه وطلــب رصدهــا يف ضبــط القضيــة‪،‬‬\n‫ونصهــا مــا يلــي‪ :‬بعــد االطــاع علــى مذكــرة االدعــاء بحقنــا واملقدمــة‬\n‫مــن املدعــي ‪ ...‬بتاريــخ ‪ 1433/06/17‬ه ـ املوافــق ‪2012/05/08‬م‪،‬‬\n‫وبعــد تفحــص تاريــخ املدعــي الوظيفــي لدينــا ومراجعــة مطالبــه مراجعــة‬\n‫شــاملة‪ ،‬نــود إيضــاح التالــي‪ )1 :‬تعــن املدعــي لــدى مؤسســة ‪ ...‬التجاريــة‬\n\n\n                                                                                    ‫‪168‬‬\n\f      ‫بوظيفــة مهنــدس ميكانيــكا يف تاريــخ ‪ )2 .1994/12/10‬مت إنهــاء‬\n      ‫خدمــات املدعــي يف تاريــخ ‪ 2000/07/24‬مــع منحــه شــهر اإلنــذار املتفق‬\n      ‫عليــه يف العقــد حتــى يــوم ‪ ،2000/08/24‬وهــو يعلــم ذلــك متــام العلــم‪،‬‬\n      ‫ومرفــق وثيقــة بخــط يــده وتوقيعــه تثبــت ذلــك وليــس كمــا ادعــى أنــه يف‬\n      ‫‪ )3 .2001/01/03‬عنــد تأخــر املدعــي يف نقــل كفالتــه بعــد إصــدار‬\n                  ‫قــرار إنهــاء خدماتــه وأخــذه وق ًتــا طويـ ًـا متــت مخاطبتــه ُ‬\n      ‫وطلـ َـب منــه‬\n      ‫كتابيا يف تاريخ ‪1421/08/02‬هـ املوافق ‪2000/10/29‬م اإلســراع يف‬               ‫ًّ‬\n      ‫نقــل الكفالــة وإال فســوف يكــون الترحيــل النهائــي مــن البلــد مصيــره‬\n      ‫ويتــم إعطــاؤه مهلــة حتــى يــوم ‪2000/11/15‬م إلمتــام ذلــك‪ ،‬وهــذا مــن‬\n      ‫حــق صاحــب العمــل إلخــاء مســئوليته أمــام اجلهــات املختصــة يف الدولــة؛‬\n      ‫حيــث كنــا يف غايــة املرونــة وطــول البــال معــه حتــى نقــل كفالتــه‪ ،‬وإال‬\n      ‫ـورا‪ ،‬إذا لــم يجــد‬\n                         ‫نهائيــا وفـ ً‬\n                                  ‫ًّ‬    ‫فــإن األنظمــة الســارية حتتــم علينــا ترحيلــه‬\n      ‫كفيـ ًـا آخــر‪ )4 .‬بالفعــل مت تس ـلُّم خطــاب طلــب نقــل كفالــة للمدعــي‬\n      ‫مــن قِ بــل مؤسســة ‪ ...‬ولكــن يف تاريــخ ‪ 2001/01/15‬أي بعــد شــهرين‬\n      ‫مــن تاريــخ نهايــة املهلــة النهائيــة املمنوحــة لــه واملذكــورة يف الفقــرة‬\n      ‫الســابقة؛ حيــث صبرنــا عليــه قرابــة ســتة أشــهر مراعــا ًة لظروفــه‪،‬‬\n      ‫ـورا ويف حينــه‪ )5 .‬طلــب املدعــي‬   ‫وقــد متــت املوافقــة علــى نقــل خدماتــه فـ ً‬\n      ‫يف تاريــخ ‪1421/05/21‬ه ـ جتديــد إقامتــه علــى حســابه اخلــاص ملــدة‬\n      ‫عــام واحــد؛ حيــث إنــه أجــرى أو ســيجري عمليــة جراحيــة وقتهــا وفتــرة‬\n      ‫الصالحيــة املتبقيــة يف اإلقامــة ‪1421/07/01‬ه ـ قــد ال تكــون كافيــة‬\n      ‫لــه للتعــايف مــن العمليــة علــى حــد وصفــه وقــد مت لــه مــا أراد‪ ..‬طلبــات‬\n      ‫نصــا يف وثيقــة االدعــاء والــرد عليهــا‪ -1 :‬مبلــغ‬   ‫املدعــي كمــا وردت ًّ‬\n      ‫‪ 12910‬ريــاالت نهايــة اخلدمــة مــن ‪1994/12/10‬م إلــى ‪2001/01/03‬م‬\n\n\n‫‪169‬‬\n\f‫مطلقــا يف منحــه مكافــأة نهايــة خدمتــه مــن تاريــخ تعيينــه يف‬  ‫ً‬         ‫لــم منانــع‬\n‫‪ 1994/12/10‬إلــى آخــر يــوم عملــه يف ‪ 2000/08/24‬اســتنا ًدا للقاعــدة‬\n‫الشــرعية بــأن األجــر مقابــل العمــل؛ حيــث قــال رســول اهلل صلــى‬\n‫اهلل عليــه وســلم‪« :‬أعطــوا األجيــر أجــره قبــل أن يجــف عرقــه»‪ ،‬وهــو‬\n‫كان أجيـ ًـرا يعمــل لدينــا بأجــر مقابــل العمــل الــذي يؤديــه حتــى تاريــخ‬\n‫مطلقــا‪،‬‬\n     ‫ً‬      ‫‪ 2000/08/24‬ومــن بعــد هــذا التاريــخ لــم يقــم بالعمــل لدينــا‬\n‫وبالتالــي فــا يســتحق أي نــوع مــن التعويــض أو األجــر بعــد آخــر يــوم‬\n‫ـاء علــى إنهــاء خدماتــه مــن املؤسســة‪ ،‬وهــذا حــق كفلــه لنــا‬      ‫عمــل لــه بنـ ً‬\n‫الشــرع والعــرف واألنظمــة ذات العالقــة نظــام العمــل والعمــال الســعودي‪.‬‬\n‫ـال مقابــل إجــازة غيــر مدفوعــة رصيــد اإلجــازات‬         ‫‪ -2‬مبلــغ ‪ 4591‬ريـ ً‬\n‫املســتحقة‪ ،‬والتــي لــم يســتخدمها املوظــف ســوف تضــاف إلــى مخالصــة‬\n‫نهايــة اخلدمــة وال يشــمل ذلــك اإلجــازات غيــر املدفوعــة حســب نظــام‬\n‫العمــل والعمــال الســعودي والعقــد املبــرم معــه‪ ،‬وليــس لــه أي حــق يف هــذا‬\n‫ـال الرواتــب املتأخــرة‬‫رفــا‪ -3 .‬مبلــغ ‪ 22113‬ريـ ً‬  ‫وع ً‬\n                                                         ‫ـرعا وعقـ ًـا ُ‬  ‫الطلــب شـ ً‬\n‫مــن ‪ 2000/07/01‬إلــى ‪ 2001/01/03‬م كمــا أوضحنــا يف الفقــرة‬\n‫األولــى لــم منانــع مــن تســليمه مســتحقات نهايــة اخلدمــة مبــا فيهــا الرواتــب‬\n‫التــي لــم يتســلمها حتــى تاريــخ آخــر يــوم عمــل للموظــف‪ ،‬والــذي كان يف‬\n‫‪ 2000/08/24‬وليــس حســب التاريــخ الــذي طلبــه هــو‪ ،‬فاألجــر مقابــل‬\n‫العمــل‪ - 4 .‬مبلــغ ‪ 2000‬ريــال مدفوعــة مــن قِ بلــه ملستشــفى‪ ...‬منهــا‬\n‫حيويــا‪ ..‬ومطلــوب تزويدنــا بالتقريــر الطبــي عــن احلالــة‪،‬‬ ‫ًّ‬    ‫‪ 1080‬مضــا ًّدا‬\n‫مــع كشــف فاتــورة األدويــة‪ ،‬وإرفــاق موافقــة املؤسســة الكتابيــة علــى‬\n‫العــاج حســب نظــام العــاج يف املؤسســة‪ ،‬مــع التأكيــد علــى أننــا ســوف‬\n‫نعــوض املوظــف حــال توفيــره املطلــوب حســب سياســة العــاج الطبــي‬\n\n\n                                                                                              ‫‪170‬‬\n\f      ‫للمؤسســة‪ ،‬وخــال الفتــرة التــي كان فيهــا حتــت كفالــة املؤسســة‬\n      ‫فقــط؛ أي أن أيــة مطالبــة بعــد نقــل الكفالــة هــي مطالبــة غيــر مقبولــة‪.‬‬\n      ‫‪ -5‬مبلــغ‪ 4000‬ريــال غيــارات ومطهــرات وأدويــة وكشــوفات مــن‬\n      ‫‪ 2000/09/01‬حتــى ‪2001/01/03‬م ومطلــوب تزويدنــا بالتقريــر‬\n      ‫الطبــي عــن احلالــة‪ ،‬مــع كشــف فاتــورة األدويــة‪ ،‬وإرفــاق موافقــة‬\n      ‫املؤسســة الكتابيــة علــى العــاج حســب نظــام العــاج يف املؤسســة‪،‬‬\n      ‫مــع التأكيــد علــى أننــا ســوف نعــوض املوظــف حــال توفيــره املطلــوب‬\n      ‫حســب سياســة العــاج الطبــي للمؤسســة وخــال الفتــرة التــي كان فيها‬\n      ‫حتــت كفالــة املؤسســة فقــط أي أن أيــة مطالبــة بعــد نقــل الكفالــة هــي‬\n      ‫مطالبــة غيــر مقبولــة ا‪.‬هــ‪ .‬وبــرد ذلــك علــى املدعــي طلــب املهلــة للــرد علــى‬\n      ‫آنفــا‪،‬‬\n           ‫هــذه املذكــرة املقدمــة مــن املدعــى عليــه بالوكالــة واملرصــودة ً‬\n      ‫بعــد أن جــرى تزويــده بنســخة منهــا ورفعــت اجللســة‪ ..‬ويف جلســة أخــرى‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي و املدعــى عليــه وكالــة املرصــودة‬\n      ‫آنفــا‪ ،‬وقــرر املدعــي بقولــه‪ :‬إننــي بعــد اطالعــي علــى املذكــرة‬   ‫بياناتهمــا ً‬\n      ‫التــي قدمهــا لــي املدعــى عليــه وكالـ ًة يف اجللســة املاضيــة لــم أجــد فيهــا‬\n      ‫ـدي إضافــة ســوى مــا أوردتــه‬ ‫مــا يســتوجب منــي الــرد عليهــا؛ لــذا فليــس لـ َّ‬\n      ‫يف دعــواي؛ هكــذا قــرر‪ .‬وبســؤال املدعــى عليــه وكال ـ ًة عــن العقــد‬\n      ‫املبــرم بــن املدعــي واملؤسســة موكلتــه اســتعد بإحضــار نســخة منــه يف‬\n      ‫اجللســة القادمــة؛ لــذا فقــد جــرى رفــع اجللســة‪ ..‬ويف جلســة أخــرى حضــر‬\n      ‫آنفــا‪ ،‬وقــد أبــرز لنــا‬\n                             ‫املدعــي واملدعــى عليــه وكالــة املرصــودة بياناتهمــا ً‬\n      ‫املدعــى عليــه بالوكالــة نســخة مــن عقــد االتفــاق املكــون مــن أربــع‬\n      ‫صفحــات فوجدتــه يحمــل مطبوعــات املؤسســة موكلــة املدعــى عليــه‪،‬‬\n      ‫وبعرضــه علــى املدعــي صــادق عليــه‪ ..‬ولالطــاع علــى هــذا العقــد وتأمــل‬\n\n\n‫‪171‬‬\n\f‫القضيــة جــرى رفــع اجللســة‪ ،‬ويف جلســة أخــرى افتتحــت اجللســة وفيهــا‬\n‫آنفــا‪ ،‬وقــد‬\n            ‫حضــر املدعــي واملدعــى عليــه وكالــة املرصــودة بياناتهمــا ً‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى‬\n                                ‫جــرى منــي تأمــل القضيــة ودراســتها؛ فبنـ ً‬\n‫واإلجابــة وبعــد االطــاع علــى نســخة العقــد الــذي قدمــه املدعــى عليــه‬\n‫آنفــا‪ ،‬وحيــث إن النظــر يف االختصــاص النوعــي‬    ‫وكال ـ ًة واملشــار إليــه ً‬\n‫مقــدم علــى النظــر يف موضــوع الدعــوى‪ ،‬وحيــث ظهــر لــي أن نظــر هــذه‬\n‫القضيــة خــارج اختصــاص احملاكــم العامــة ملــا نصــت عليــه الفقــرة‬\n‫األولــى مــن املــادة اخلامســة مــن نظــام العمــل‪ ،‬والتــي بينــت ســريان‬\n‫أحــكام نظــام العمــل ونــص الفقــرة املشــار إليهــا‪ :‬كل عقــد عمــل‬\n‫يلتــزم مبقتضــاه أي شــخص بالعمــل ملصلحــة صاحــب العمــل وحتــت‬\n‫إدارتــه أو إشــرافه مقابــل أجــر ا‪.‬هــ‪ ،‬وحيــث إن نظــر القضايــا العماليــة‬\n‫مــن اختصــاص هيئــة تســوية اخلالفــات العماليــة مبكتــب العمــل؛ لــذا‬\n‫فقــد صرفــت النظــر عــن مطالبــة املدعــي لعــدم االختصــاص الوالئــي‬\n‫ومبــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــي قــرر عــدم القناعــة‬\n‫باحلكــم‪ ،‬وطلــب االســتئناف بــدون الئحــة اعتراضيــة‪ ..‬وقــرر املدعــى‬\n‫عليــه بالوكالــة قناعتــه باحلكــم‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف ‪1434/4/6‬هــ‪.‬‬\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34221355‬وتاريــخ‬\n                                                 ‫‪1434/5/25‬هـ‬\n\n\n\n\n                                                                                   ‫‪172‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":166,"source_page_end":172,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"58910c4c5a01a301c0de908c9793b8cf76c58e4640d191073dcb92c8693dc203","normalized_text_hash":"f335d8a915bee1726e6cf4b07039473cfce77d15b8f48f62f2718474f6034549","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p166-34181516"},{"id":"53498b18-2deb-52b0-8863-33dd034adc32","document_type":"judgment","category":"judicial","subcategory":"general","title":"ض -إعاد ة البلك حمل له ناشئ ة عن إثبات مت ل","document_number":"34175102","case_number":"33335945","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/29","year":"1434","subject":"ض -إعاد ة البلك حمل له ناشئ ة عن إثبات مت ل","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه ‪1434/3/29 :‬هـ‬\n                       ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك ‪34175102 :‬‬\n                         ‫َر ْق ُم الدعوى ‪33335945 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34249121‬تاريخه ‪1434/6/24 :‬هـ‬\n\n\n        ‫ـض‪ -‬إعــاد ُة البلــك حمل ِّلــه ناشــئ ٌة َعــن إثبــاتِ مت ُّلـ ِ‬\n       ‫ـك‬                                                                  ‫ـاص‪ -‬تعويـ ٌ‬ ‫ِصـ ٌ‬\n                                                                                            ‫اخت َ‬\n       ‫العامـةِ‪َ -‬دعــا َوى‬\n                      ‫َّ‬    ‫ـاص احملكمـ ِة‬     ‫األراضــي اخ ِتصـ ُ‬\n                                                             ‫ِ‬         ‫ـك‬‫ـوت مت ُّلـ ِ‬\n                                                                                   ‫األرض ‪ -‬ثبـ ُ‬\n                                                                                             ‫ِ‬\n                                                      ‫للحيــاز ِة ‪ -‬عـ َـد ُم اخ ِتصـ ٍ‬\n                                         ‫ـاص نوعـ ٍّـي‪.‬‬                              ‫ض ِ‬  ‫ال َّتعـ ُّـر ِ‬\n\n\n\n\n       ‫ـاء قضي ِتــه باألمـ ِ‬\n       ‫ـس‬                      ‫ـك قضـ ُ‬  ‫مينعـ َ‬\n                                            ‫ُ‬                       ‫رضــي ا ُ‬\n                                                    ‫هلل عن ـ ُه‪( :‬وال‬        ‫‪1 .1‬قــولُ عمـ َـر ِ‬\n        ‫لرشــدِ َك ْأن ترجـ َـع للحـ ِّـق)‪.‬‬\n                                          ‫وهديـ َـت في ـ ِه ُ‬\n                                                           ‫ـك ُ‬       ‫فراجعـ َـت في ـ ِه َ‬\n                                                                   ‫نفسـ َ‬\n                         ‫العامةِ‪.‬‬\n                            ‫َّ‬    ‫احملاكم‬\n                                  ‫ِ‬            ‫اختصاص‬\n                                                 ‫ُ‬            ‫للحياز ِة‬\n                                                                     ‫ض ِ‬   ‫عر ِ‬\n                                                                              ‫‪َ 2 .2‬دعا َوى ال َّت ُّ‬\n\n\n\n       ‫ـام‬\n         ‫أرض ل ـ ُه‪ ،‬فقـ َ‬  ‫ـوير ٍ‬ ‫ـف بلك ـ ٍة لتسـ ِ‬   ‫بو ْضـ ِـع ألـ ِ‬ ‫ـام َ‬      ‫املدعِ ــي بأ َّن ـ ُه قـ َ‬\n                                                                                                            ‫ا َّد َعــى َّ‬\n       ‫ـام بنقـ ِـل‬ ‫ن بلك ـ ًة‪ ،‬وقـ َ‬    ‫ـير مائ ـ ٍة وثـ َـاث وخمس ـ َ‬            ‫املد َعــى علي ـ ِه بتكسـ ِ‬           ‫َّ‬\n       ‫املد َعــى‬     ‫ن بلك ـ ًة قُ راب ـ َة مائ ـ ِة متـ ٍـر‪ ،‬ويطلـ ُـب إلـ َ‬\n                ‫ـزام َّ‬                                                               ‫وســبع وأربع ـ َ‬     ‫ثمامنا َئــة َ‬\n       ‫وتعويض ـ ُه عـ ِـن البلـ ِـك املكســو ِر ‪ ،‬صــا َد َق‬  ‫َ‬           ‫علي ـ ِه بإعــاد ِة البلـ ِـك حمل ِّل ـ ِه‬\n       ‫الطريـ ِـق‬ ‫ـرم َّ‬\n                       ‫املد َعــى عليـ ِه ع َلــى قيامِ ــه بنقـ ِـل البلـ ِـك‪ ،‬وذلـ َـك إلبعــادِه َعــن َحـ ِ‬             ‫َّ‬\n       ‫أن مركـ َـز الشــرط ِة لدي ـ ِه‬       ‫ـير البلـ ِـك‪ ،‬وذكـ َـر َّ‬      ‫قيام ـ ُه بتكسـ ِ‬        ‫وأنكـ َـر َ‬\n       ‫املدعِ ــي قــالَ ‪:‬‬\n                         ‫ـرض ذلـ َـك علــى َّ‬  ‫ـدر محضـ ٌـر بالواقع ـةِ‪ .‬وبعـ ِ‬              ‫عِ لـ ٌـم بذلـ َـك وصـ َ‬\n       ‫ـاء بدعـ َـو ُاه وصــا َد َق علــى حتريـ ِـر مركـ ِـز الشــرط ِة‬                ‫الصحيـ ُـح هـ َـو مــا جـ َ‬    ‫َّ‬\n       ‫ـاء يف محضـ ِـر املعاين ـ ِة‬   ‫ـرت الكتاب ـ ُة ملركـ ِـز الشــرطةِ‪ ،‬وجـ َ‬                    ‫للواقع ـ ِة ‪،‬جـ ِ‬\n                                                                                                                  ‫َ‬\n\n‫‪173‬‬\n\f‫ـك مكسـ ٌـر‬   ‫األرض املتنــاز َع علي َهــا بلـ ٌ‬    ‫َ‬       ‫أن‬‫أ َّن ـ ُه باالنتقــالِ للموقـ ِـع ُوجـ َـد َّ‬\n‫املدعِ ــي‪َ :‬هـ ْـل لدي ـ ِه َمزيـ ُـد ِّبي َنــة؟ فقــالَ ‪َ :‬ل‪.‬‬\n                                                            ‫مت ســؤالُ َّ‬     ‫ـاء ‪َّ ،‬‬\n                                                                         